  product shoppingmall_products @relation(fields: [shoppingmall_product_id], references: [id], onDelete: Cascade)
  productOption shoppingmall_product_options? @relation(fields: [shoppingmall_product_option_id], references: [id], onDelete: Cascade)
  cartSnapshot shoppingmall_cart_snapshots? @relation(fields: [shoppingmall_cart_snapshot_id], references: [id], onDelete: Cascade)

  @@index([shoppingmall_product_id])
  @@index([shoppingmall_product_option_id])

  @@unique([shoppingmall_cart_id, shoppingmall_product_id, shoppingmall_product_option_id], map: "shoppingmall_cart_items_shoppingmall_cart_id_shoppingm_f4833d38")
  @@index([shoppingmall_cart_snapshot_id])
}

/// Snapshot of cart state at a specific point (e.g., add to cart, checkout,
/// or abandonment). Used for audit, analytics, order evidence, and recovery.
/// Contains denormalized (copied) data from the cart, customer, items, and
/// products for complete historical context.
///
/// @namespace Carts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_cart_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Cart's {@link shoppingmall_carts.id} at snapshot moment.
  shoppingmall_cart_id String @db.Uuid

  /// Snapshot trigger event ('add_item', 'checkout', 'abandon', etc.).
  snapshot_type String

  /// Serialized JSON/business data containing cart, items, prices, customer,
  /// and contextual info.
  snapshot_data String

  /// Timestamp at which the snapshot was created.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  cart shoppingmall_carts @relation(fields: [shoppingmall_cart_id], references: [id], onDelete: Cascade)

  shoppingmall_cart_items shoppingmall_cart_items[]

  @@index([shoppingmall_cart_id])
  @@index([created_at])
  @@index([snapshot_data(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Tracks carts that were abandoned by customers before checkout. Used for
/// analytics, recovery, and marketing triggers. Linked to session, customer,
/// and original cart for lifecycle tracking.
///
/// @namespace Carts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_abandoned_carts {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Abandoned cart's {@link shoppingmall_carts.id}.
  shoppingmall_cart_id String @db.Uuid

  /// Owning customer's {@link shoppingmall_customers.id}.
  shoppingmall_customer_id String @db.Uuid

  /// Session's {@link shoppingmall_sessions.id} where abandonment detected.
  shoppingmall_session_id String? @db.Uuid

  /// Timestamp the cart was marked as abandoned.
  abandoned_at DateTime @db.Timestamptz

  /// Status of recovery attempts ('none', 'emailed', 'recovered', etc.).
  recovery_status String

  /// Timestamp of successful recovery (if any); else null.
  recovered_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  cart shoppingmall_carts @relation(fields: [shoppingmall_cart_id], references: [id], onDelete: Cascade)
  customer shoppingmall_customers @relation(fields: [shoppingmall_customer_id], references: [id], onDelete: Cascade)
  session shoppingmall_sessions? @relation(fields: [shoppingmall_session_id], references: [id], onDelete: Cascade)

  @@index([shoppingmall_session_id])

  @@unique([shoppingmall_cart_id])
  @@index([shoppingmall_customer_id])
  @@index([abandoned_at])
}

/// Associates carts with channels for multi-channel shopping, analytics, and
/// cross-device/cart migration. Each record links a cart to a specific
/// channel, supporting platform analytics and personalized cross-channel
/// flows.
///
/// @namespace Carts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_cart_channels {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Linked cart's {@link shoppingmall_carts.id}.
  shoppingmall_cart_id String @db.Uuid

  /// Linked channel's {@link shoppingmall_channels.id}.
  shoppingmall_channel_id String @db.Uuid

  /// Timestamp when association was created.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  cart shoppingmall_carts @relation(fields: [shoppingmall_cart_id], references: [id], onDelete: Cascade)
  channel shoppingmall_channels @relation(fields: [shoppingmall_channel_id], references: [id], onDelete: Cascade)

  @@unique([shoppingmall_cart_id, shoppingmall_channel_id], map: "shoppingmall_cart_channels_shoppingmall_cart_id_shoppi_d455f6a8")
  @@index([shoppingmall_channel_id])
}

schemas.schema-05-orders.prisma:
/// Main order entity for the shoppingMall platform. Stores core order
/// information, customer/seller references, channel origins, parent-child
/// linkage (split orders), top-line financials (non-calculated),
/// address/delivery data, order status, and assignment to
/// compliance/evidence flows. Links to snapshots, sub-orders, order items,
/// payments, shipments, refunds, returns, disputes, and status logs. Full
/// audit and regulatory preservation. Referenced by sub-orders, payments,
/// status logs, evidence, etc.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_orders {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged customer's {@link shoppingmall_customers.id}.
  shoppingmall_customer_id String @db.Uuid

  /// Primary seller's {@link shoppingmall_sellers.id}.
  shoppingmall_seller_id String? @db.Uuid

  /// Placed sales channel {@link shoppingmall_channels.id}.
  shoppingmall_channel_id String @db.Uuid

  /// Order code, unique within channel—business order token (e.g.,
  /// ORD-YYYYMMDD-NNNN).
  order_code String

  /// Parent order for split (multi-seller) orders; null if this is the
  /// root/master order.
  parent_order_id String? @db.Uuid

  /// Sum of order item (raw price x quantity), pre-discount, pre-fee
  /// (non-calculated, actual at order submit).
  total_amount Float @db.DoublePrecision

  /// Sum of applied discounts (at commit); always ≤ total_amount.
  total_discount_amount Float? @db.DoublePrecision

  /// Order-level shipping/fulfillment fee (if paid by buyer).
  total_shipping_fee Float? @db.DoublePrecision

  /// Current order status snapshot (enum: pending, confirmed, shipped,
  /// delivered, completed, cancelled, on_hold, disputed, returned, refunded).
  order_status String

  /// Order creation source/channel (web, mobile, api, partner, etc.).
  order_source String

  /// Timestamp order was submitted by user.
  order_placed_at DateTime @db.Timestamptz

  /// Snapshot of the chosen shipping address at time of order as JSON
  /// serialized structure. Immutable per business audit.
  shipping_address_json String

  /// Recipient's name (as entered for this delivery, for audit even if
  /// different from profile).
  recipient_name String

  /// Recipient phone/contact at order time (non-keyed to user profile).
  recipient_phone String

  /// Created timestamp for order record.
  created_at DateTime @db.Timestamptz

  /// Last updated timestamp for order record.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp, null unless order record deactivated.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shoppingmall_customers @relation(fields: [shoppingmall_customer_id], references: [id], onDelete: Cascade)
  seller shoppingmall_sellers? @relation(fields: [shoppingmall_seller_id], references: [id], onDelete: Cascade)
  channel shoppingmall_channels @relation(fields: [shoppingmall_channel_id], references: [id], onDelete: Cascade)

  shoppingmall_sub_orders shoppingmall_sub_orders[]
  shoppingmall_order_payments shoppingmall_order_payments[]
  shoppingmall_order_status_logs shoppingmall_order_status_logs[]
  shoppingmall_order_snapshots shoppingmall_order_snapshots[]
  shoppingmall_order_refunds shoppingmall_order_refunds[]
  shoppingmall_order_returns shoppingmall_order_returns[]
  shoppingmall_disputes shoppingmall_disputes[]
  shoppingmall_order_evidence shoppingmall_order_evidence[]

  @@unique([order_code, shoppingmall_channel_id])
  @@index([shoppingmall_customer_id])
  @@index([shoppingmall_seller_id])
  @@index([shoppingmall_channel_id])
  @@index([parent_order_id])
  @@index([order_status, order_placed_at])
  @@index([created_at])
  @@index([recipient_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Sub-order record for multi-seller/multi-fulfillment cases. Each relates
/// to a master order and a specific seller. Captures order status, amounts,
/// and shipment cross-references. Sub-orders enable correct fulfillment,
/// cancellation, and partial refund flows. Parent order snapshotting is
/// referenced, with auditing. Links to order_items, shipments, status logs.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_sub_orders {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Referenced master order's {@link shoppingmall_orders.id}.
  shoppingmall_order_id String @db.Uuid

  /// Assigned seller (for this sub-order) {@link shoppingmall_sellers.id}.
  shoppingmall_seller_id String @db.Uuid

  /// Unique code per sub-order within parent order context (e.g.,
  /// ORD-YYYYMMDD-NNNN-S01).
  sub_order_code String

  /// Sub-order status (pending, confirmed, shipped, delivered, completed,
  /// cancelled, on_hold, disputed, returned, refunded).
  status String

  /// Total (raw) amount for this sub-order, as committed.
  total_amount Float @db.DoublePrecision

  /// Total applied discount on sub-order.
  total_discount_amount Float? @db.DoublePrecision

  /// Shipping/fulfillment fee on sub-order (if borne by buyer).
  total_shipping_fee Float? @db.DoublePrecision

  /// Sub-order creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last updated timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp, null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  order shoppingmall_orders @relation(fields: [shoppingmall_order_id], references: [id], onDelete: Cascade)
  seller shoppingmall_sellers @relation(fields: [shoppingmall_seller_id], references: [id], onDelete: Cascade)

  shoppingmall_order_items shoppingmall_order_items[]
  shoppingmall_order_shipments shoppingmall_order_shipments[]
  shoppingmall_order_status_logs shoppingmall_order_status_logs[]

  @@unique([sub_order_code, shoppingmall_order_id], map: "shoppingmall_sub_orders_sub_order_code_shoppingmall_or_5204d994")
  @@index([shoppingmall_order_id])
  @@index([shoppingmall_seller_id])
  @@index([status])
  @@index([sub_order_code(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Order line items. Each references product snapshot and sub-order.
/// Captures product option, quantity, unit/total price at order commit,
/// per-business and audit rules. Supports reference to product snapshot for
/// audit and recovery. Enables evidence linkage and refund/return
/// calculation per item. No denormalization of live product info, strict
/// snapshot architecture. Indexed by sub-order, product, and code.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_order_items {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Related sub-order {@link shoppingmall_sub_orders.id}.
  shoppingmall_sub_order_id String @db.Uuid

  /// Snapshot of product at order-time for this item {@link
  /// shoppingmall_product_snapshots.id}.
  shoppingmall_product_snapshot_id String @db.Uuid

  /// Serialized product option/sku snapshot as JSON at time of order (for
  /// audit, e.g., color, size).
  product_option_json String

  /// Human-facing product code at order time (for audit).
  product_code String

  /// Product display name at order time (snapshot, audit).
  product_name String

  /// Purchased quantity for this item.
  quantity Int @db.Integer

  /// Per-unit price at order commit (actual raw price, not calculated current
  /// price).
  unit_price Float @db.DoublePrecision

  /// Extended price (=unit_price x quantity) at commit.
  total_price Float @db.DoublePrecision

  /// Order item record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Order item record last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp; null unless removed.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  subOrder shoppingmall_sub_orders @relation(fields: [shoppingmall_sub_order_id], references: [id], onDelete: Cascade)
  productSnapshot shoppingmall_product_snapshots @relation(fields: [shoppingmall_product_snapshot_id], references: [id], onDelete: Cascade)

  @@index([shoppingmall_sub_order_id])
  @@index([shoppingmall_product_snapshot_id])
  @@index([product_code])
  @@index([created_at])
  @@index([product_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Tracks all payment attempts for orders (initial, retry, split, partial,
/// failed, completed). References order, payer, payment method, gateway,
/// amount, status, and evidence. Follows full payment evidence and
/// reconciliation audit requirements. Used for refund initiation and
/// compliance linkage. No calculated fields, payment status and method must
/// be business-audited.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_order_payments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Related order {@link shoppingmall_orders.id}.
  shoppingmall_order_id String @db.Uuid

  /// Paying customer reference {@link shoppingmall_customers.id}.
  shoppingmall_customer_id String @db.Uuid

  /// Unique business payment transaction code, for support/audit.
  payment_code String

  /// Payment amount for this transaction (snapshotted at payment submit).
  amount Float @db.DoublePrecision

  /// 3-letter ISO currency code (e.g., USD, EUR, KRW).
  currency String

  /// Payment method (card, bank_transfer, deposit, coupon, mileage, ewallet,
  /// cod, etc.).
  payment_method String

  /// Payment gateway/provider/business system (e.g., stripe, paypal,
  /// wirebarley, bank name, or internal).
  payment_gateway String

  /// Current payment status (pending, success, failed, cancelled, on_hold,
  /// refunded, disputed).
  payment_status String

  /// Timestamp of payment submission/commit.
  paid_at DateTime @db.Timestamptz

  /// Gateway/reference transaction id/result for reconciliation.
  gateway_transaction_id String?

  /// Payment record created at timestamp.
  created_at DateTime @db.Timestamptz

  /// Payment record last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft delete for payment record if rolled back/erased.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  order shoppingmall_orders @relation(fields: [shoppingmall_order_id], references: [id], onDelete: Cascade)
  customer shoppingmall_customers @relation(fields: [shoppingmall_customer_id], references: [id], onDelete: Cascade)

  shoppingmall_order_refunds shoppingmall_order_refunds[]

  @@unique([payment_code])
  @@unique([gateway_transaction_id])
  @@index([shoppingmall_order_id])
  @@index([shoppingmall_customer_id])
  @@index([payment_method])
  @@index([payment_status])
}

/// Shipment/fulfillment records per (sub-)order. Tracks logistics
/// carrier/service, tracking code, fulfillment status, ship/receive/return
/// timestamps, and delivery audit. Primary linkage is to sub-order; supports
/// multi-shipment and partial fulfillment. All critical operations and
/// evidence linked for compliance. Supports returns, disputes, and delivery
/// tracking/audit.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_order_shipments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Related sub-order to which shipment is attached {@link
  /// shoppingmall_sub_orders.id}.
  shoppingmall_sub_order_id String @db.Uuid

  /// Internal shipment/tracking code for business use.
  shipment_code String

  /// Logistics company or carrier reference (business-facing).
  carrier String

  /// Carrier-assigned tracking id/code.
  tracking_number String?

  /// Shipment fulfillment status (pending, ready, in_transit, delivered,
  /// returned, cancelled, failed, lost, on_hold).
  fulfillment_status String

  /// Timestamp parcel was handed off to carrier/logistics.
  shipped_at DateTime? @db.Timestamptz

  /// Timestamp parcel was officially delivered/accepted.
  delivered_at DateTime? @db.Timestamptz

  /// Timestamp of return-to-sender or failed delivery (if returned).
  returned_at DateTime? @db.Timestamptz

  /// JSON serial of the delivery/shipping address used (immutable for audit).
  delivery_address_json String

  /// Name or contact of person who physically received parcel, as known at
  /// delivery time.
  received_by String?

  /// Created timestamp for shipment record.
  created_at DateTime @db.Timestamptz

  /// Updated timestamp for shipment record.
  updated_at DateTime @db.Timestamptz

  /// Soft delete, if shipment voided/erased.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  subOrder shoppingmall_sub_orders @relation(fields: [shoppingmall_sub_order_id], references: [id], onDelete: Cascade)

  shoppingmall_disputes shoppingmall_disputes[]

  @@unique([shipment_code])
  @@index([shoppingmall_sub_order_id])
  @@index([carrier])
  @@index([fulfillment_status])
  @@index([tracking_number])
  @@index([carrier(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Immutable audit trail of all order & sub-order status transitions, with
/// actor, status before/after, timestamp, channel/context, and linkage to
/// compliance evidence where needed. Enables full lifecycle reconstruction
/// for audit/compliance/dispute. Used by admins for root cause and SLA
/// monitoring. Status log is append-only, write-once. Channel context for
/// multi-channel orders is preserved. Links to orders, sub-orders, and
/// evidence snapshots.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_order_status_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Main order mapped to this status change log {@link
  /// shoppingmall_orders.id}.
  shoppingmall_order_id String @db.Uuid

  /// Sub-order mapped to this status change log (if applicable) {@link
  /// shoppingmall_sub_orders.id}.
  shoppingmall_sub_order_id String? @db.Uuid

  /// Actor account triggering status change (customer, seller, admin) {@link
  /// shoppingmall_actor_profiles.id}.
  shoppingmall_actor_id String @db.Uuid

  /// Channel/platform where status change originated (web, mobile, api, admin).
  action_channel String

  /// Status before change occurred.
  status_before String?

  /// Status after change occurred.
  status_after String

  /// Business reason or code for status transition.
  transition_reason String?

  /// Arbitrary business logic memo or note for this transition (internal/audit
  /// only).
  transition_memo String?

  /// Timestamp at which status change took place.
  transition_at DateTime @db.Timestamptz

  /// Creation timestamp for log record.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order shoppingmall_orders @relation(fields: [shoppingmall_order_id], references: [id], onDelete: Cascade)
  subOrder shoppingmall_sub_orders? @relation(fields: [shoppingmall_sub_order_id], references: [id], onDelete: Cascade)
  actor shoppingmall_actor_profiles @relation(fields: [shoppingmall_actor_id], references: [id], onDelete: Cascade)

  @@index([shoppingmall_order_id])
  @@index([shoppingmall_sub_order_id])
  @@index([shoppingmall_actor_id])
  @@index([status_before, status_after])
  @@index([transition_at])
}

/// Immutable full-order snapshots for audit and compliance. Captures the
/// complete state (all business fields) of orders at critical points
/// (creation, payment, fulfillment, refund, dispute, etc.) for
/// evidence/audit purposes. Enables historical restoration, regulatory
/// export, and state transition analysis. Snapshot data are denormalized
/// JSON blobs, not real-time editable. Linked to original order.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_order_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Order to which this snapshot belongs {@link shoppingmall_orders.id}.
  shoppingmall_order_id String @db.Uuid

  /// Nature of snapshot event (created, paid, shipped, delivered, refunded,
  /// disputed, etc.).
  snapshot_type String

  /// Serialized JSON of the full order+items+shipments state at snapshot time.
  snapshot_data_json String

  /// Snapshot record creation timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order shoppingmall_orders @relation(fields: [shoppingmall_order_id], references: [id], onDelete: Cascade)

  @@index([shoppingmall_order_id])
  @@index([snapshot_type])
  @@index([created_at])
}

/// Refund/return payment flows attached to an order and often a sub-order or
/// specific item. Tracks refund amount, payment association, reason, admin
/// handling, and full audit trail for regulatory/compliance. Linked to
/// original payment, refund evidence, and status transitions. Governance for
/// partial/complete refunds, audit recovery, and regulatory SLA compliance.
/// No calculated fields (all values snapped at refund event).
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_order_refunds {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent order {@link shoppingmall_orders.id}.
  shoppingmall_order_id String @db.Uuid

  /// Original payment transaction related to refund {@link
  /// shoppingmall_order_payments.id}.
  shoppingmall_payment_id String @db.Uuid

  /// Unique refund transaction code (business/audit ref).
  refund_code String

  /// Refunded amount for this event as of the snapshot.
  refund_amount Float @db.DoublePrecision

  /// Current refund status (pending, success, failed, cancelled, on_hold,
  /// disputed).
  refund_status String

  /// Reason provided for this refund, business/audit context.
  reason String?

  /// Role requesting refund (customer, seller, admin).
  requested_by_role String

  /// Role processing/approving refund (admin, seller, system).
  processed_by_role String

  /// Timestamp refund was requested/submitted.
  requested_at DateTime @db.Timestamptz

  /// Timestamp processed/approved/denied/failed.
  processed_at DateTime? @db.Timestamptz

  /// Refund record creation timestamp (business audit).
  created_at DateTime @db.Timestamptz

  /// Refund record last updated (audit trail/compliance).
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order shoppingmall_orders @relation(fields: [shoppingmall_order_id], references: [id], onDelete: Cascade)
  payment shoppingmall_order_payments @relation(fields: [shoppingmall_payment_id], references: [id], onDelete: Cascade)

  shoppingmall_order_returns shoppingmall_order_returns[]
  shoppingmall_disputes shoppingmall_disputes[]

  @@unique([refund_code])
  @@index([shoppingmall_order_id])
  @@index([shoppingmall_payment_id])
  @@index([refund_status])
  @@index([requested_by_role])
}

/// Return requests (prior to refund) attached to orders, sub-orders, and
/// items. Contains business logic for eligibility (date, condition), scope,
/// reason, and processing details. Linked to refund flows when approved.
/// Tracks processing/admin roles, evidence, and audit trail for regulatory.
/// Supports multi-item, partial, or complete returns per order. Each return
/// record is uniquely linked to order, items, and refund when approved.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_order_returns {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Order containing the item(s) to return {@link shoppingmall_orders.id}.
  shoppingmall_order_id String @db.Uuid

  /// Refund record created if/when return is approved/paid {@link
  /// shoppingmall_order_refunds.id}.
  shoppingmall_refund_id String? @db.Uuid

  /// Unique return request code for audit/business trace.
  return_code String

  /// Type: full or partial (itemized).
  return_type String

  /// Current status (pending, approved, rejected, cancelled, returned,
  /// completed, failed, on_hold).
  status String

  /// Customer/business reason for initiating return.
  reason String?

  /// JSON array of items and quantities to return (structured for itemized
  /// returns).
  item_list_json String

  /// Who initiated: customer, seller, or admin?
  requested_by_role String

  /// Approver/process role: admin, seller, system.
  processed_by_role String

  /// Return requested timestamp.
  requested_at DateTime @db.Timestamptz

