  //----
  // RELATIONS
  //----
  reporter shoppingmall_actor_profiles @relation(fields: [reported_by_id], references: [id], onDelete: Cascade)
  comment shoppingmall_comments? @relation(fields: [target_comment_id], references: [id], onDelete: Cascade)
