  target_inquiry_id String? @db.Uuid

  /// Flagged review's {@link shoppingmall_reviews.id}, if content is review.
  target_review_id String? @db.Uuid

  /// Flagged bulletins's {@link shoppingmall_bulletins.id}, if content is
  /// bulletin.
  target_bulletin_id String? @db.Uuid

  /// Flag category code: abuse, spam, copyright, prohibited, etc. Used for
