  //----
  // RELATIONS
  //----
  flaggedBy shoppingmall_actor_profiles @relation(fields: [flagged_by_id], references: [id], onDelete: Cascade)
  comment shoppingmall_comments? @relation(fields: [target_comment_id], references: [id], onDelete: Cascade)
  article shoppingmall_articles? @relation(fields: [target_article_id], references: [id], onDelete: Cascade)
  inquiry shoppingmall_inquiries? @relation(fields: [target_inquiry_id], references: [id], onDelete: Cascade)
  review shoppingmall_reviews? @relation(fields: [target_review_id], references: [id], onDelete: Cascade)
  bulletin shoppingmall_bulletins? @relation(fields: [target_bulletin_id], references: [id], onDelete: Cascade)

  @@index([target_comment_id])
