  ruleAssignment shoppingmall_rule_assignments @relation(fields: [shoppingmall_rule_assignment_id], references: [id], onDelete: Cascade, map: "shoppingmall_rule_applications_shoppingmall_rule_assig_b70b0c5d")

  @@index([shoppingmall_business_rule_id], map: "shoppingmall_rule_applications_shoppingmall_business_r_3d9b57c8")
