  /// Human-facing product code at order time (for audit).
  product_code String

  /// Product display name at order time (snapshot, audit).
  product_name String

  /// Purchased quantity for this item.
  quantity Int @db.Integer

  /// Per-unit price at order commit (actual raw price, not calculated current
  /// price).
  unit_price Float @db.DoublePrecision

  /// Extended price (=unit_price x quantity) at commit.
  total_price Float @db.DoublePrecision

  /// Order item record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Order item record last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp; null unless removed.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  subOrder shoppingmall_sub_orders @relation(fields: [shoppingmall_sub_order_id], references: [id], onDelete: Cascade)
  productSnapshot shoppingmall_product_snapshots @relation(fields: [shoppingmall_product_snapshot_id], references: [id], onDelete: Cascade)

  @@index([shoppingmall_sub_order_id])
  @@index([shoppingmall_product_snapshot_id])
  @@index([product_code])
  @@index([created_at])
  @@index([product_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Tracks all payment attempts for orders (initial, retry, split, partial,
/// failed, completed). References order, payer, payment method, gateway,
/// amount, status, and evidence. Follows full payment evidence and
/// reconciliation audit requirements. Used for refund initiation and
/// compliance linkage. No calculated fields, payment status and method must
/// be business-audited.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_order_payments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Related order {@link shoppingmall_orders.id}.
  shoppingmall_order_id String @db.Uuid

  /// Paying customer reference {@link shoppingmall_customers.id}.
  shoppingmall_customer_id String @db.Uuid

  /// Unique business payment transaction code, for support/audit.
  payment_code String

  /// Payment amount for this transaction (snapshotted at payment submit).
  amount Float @db.DoublePrecision

  /// 3-letter ISO currency code (e.g., USD, EUR, KRW).
  currency String

  /// Payment method (card, bank_transfer, deposit, coupon, mileage, ewallet,
  /// cod, etc.).
  payment_method String

  /// Payment gateway/provider/business system (e.g., stripe, paypal,
  /// wirebarley, bank name, or internal).
  payment_gateway String

  /// Current payment status (pending, success, failed, cancelled, on_hold,
  /// refunded, disputed).
  payment_status String

  /// Timestamp of payment submission/commit.
  paid_at DateTime @db.Timestamptz

  /// Gateway/reference transaction id/result for reconciliation.
  gateway_transaction_id String?

  /// Payment record created at timestamp.
  created_at DateTime @db.Timestamptz

  /// Payment record last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft delete for payment record if rolled back/erased.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  order shoppingmall_orders @relation(fields: [shoppingmall_order_id], references: [id], onDelete: Cascade)
  customer shoppingmall_customers @relation(fields: [shoppingmall_customer_id], references: [id], onDelete: Cascade)

  shoppingmall_order_refunds shoppingmall_order_refunds[]

  @@unique([payment_code])
  @@unique([gateway_transaction_id])
  @@index([shoppingmall_order_id])
  @@index([shoppingmall_customer_id])
  @@index([payment_method])
  @@index([payment_status])
}

/// Shipment/fulfillment records per (sub-)order. Tracks logistics
/// carrier/service, tracking code, fulfillment status, ship/receive/return
/// timestamps, and delivery audit. Primary linkage is to sub-order; supports
/// multi-shipment and partial fulfillment. All critical operations and
/// evidence linked for compliance. Supports returns, disputes, and delivery
/// tracking/audit.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_order_shipments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Related sub-order to which shipment is attached {@link
  /// shoppingmall_sub_orders.id}.
  shoppingmall_sub_order_id String @db.Uuid

  /// Internal shipment/tracking code for business use.
  shipment_code String

  /// Logistics company or carrier reference (business-facing).
  carrier String

  /// Carrier-assigned tracking id/code.
  tracking_number String?

  /// Shipment fulfillment status (pending, ready, in_transit, delivered,
  /// returned, cancelled, failed, lost, on_hold).
  fulfillment_status String

  /// Timestamp parcel was handed off to carrier/logistics.
  shipped_at DateTime? @db.Timestamptz

  /// Timestamp parcel was officially delivered/accepted.
  delivered_at DateTime? @db.Timestamptz

  /// Timestamp of return-to-sender or failed delivery (if returned).
  returned_at DateTime? @db.Timestamptz

  /// JSON serial of the delivery/shipping address used (immutable for audit).
  delivery_address_json String

  /// Name or contact of person who physically received parcel, as known at
  /// delivery time.
  received_by String?

  /// Created timestamp for shipment record.
  created_at DateTime @db.Timestamptz

  /// Updated timestamp for shipment record.
  updated_at DateTime @db.Timestamptz

  /// Soft delete, if shipment voided/erased.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  subOrder shoppingmall_sub_orders @relation(fields: [shoppingmall_sub_order_id], references: [id], onDelete: Cascade)

  shoppingmall_disputes shoppingmall_disputes[]

  @@unique([shipment_code])
  @@index([shoppingmall_sub_order_id])
  @@index([carrier])
  @@index([fulfillment_status])
  @@index([tracking_number])
}

/// Immutable audit trail of all order & sub-order status transitions, with
/// actor, status before/after, timestamp, channel/context, and linkage to
/// compliance evidence where needed. Enables full lifecycle reconstruction
/// for audit/compliance/dispute. Used by admins for root cause and SLA
/// monitoring. Status log is append-only, write-once. Channel context for
/// multi-channel orders is preserved. Links to orders, sub-orders, and
/// evidence snapshots.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_order_status_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Main order mapped to this status change log {@link
  /// shoppingmall_orders.id}.
  shoppingmall_order_id String @db.Uuid

  /// Sub-order mapped to this status change log (if applicable) {@link
  /// shoppingmall_sub_orders.id}.
  shoppingmall_sub_order_id String? @db.Uuid

  /// Actor account triggering status change (customer, seller, admin) {@link
  /// shoppingmall_actor_profiles.id}.
  shoppingmall_actor_id String @db.Uuid

  /// Channel/platform where status change originated (web, mobile, api, admin).
  action_channel String

  /// Status before change occurred.
  status_before String?

  /// Status after change occurred.
  status_after String

  /// Business reason or code for status transition.
  transition_reason String?

  /// Arbitrary business logic memo or note for this transition (internal/audit
  /// only).
  transition_memo String?

  /// Timestamp at which status change took place.
  transition_at DateTime @db.Timestamptz

  /// Creation timestamp for log record.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order shoppingmall_orders @relation(fields: [shoppingmall_order_id], references: [id], onDelete: Cascade)
  subOrder shoppingmall_sub_orders? @relation(fields: [shoppingmall_sub_order_id], references: [id], onDelete: Cascade)
  actor shoppingmall_actor_profiles @relation(fields: [shoppingmall_actor_id], references: [id], onDelete: Cascade)

  @@index([shoppingmall_order_id])
  @@index([shoppingmall_sub_order_id])
  @@index([shoppingmall_actor_id])
  @@index([status_before, status_after])
  @@index([transition_at])
}

/// Immutable full-order snapshots for audit and compliance. Captures the
/// complete state (all business fields) of orders at critical points
/// (creation, payment, fulfillment, refund, dispute, etc.) for
/// evidence/audit purposes. Enables historical restoration, regulatory
/// export, and state transition analysis. Snapshot data are denormalized
/// JSON blobs, not real-time editable. Linked to original order.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_order_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Order to which this snapshot belongs {@link shoppingmall_orders.id}.
  shoppingmall_order_id String @db.Uuid

  /// Nature of snapshot event (created, paid, shipped, delivered, refunded,
  /// disputed, etc.).
  snapshot_type String

  /// Serialized JSON of the full order+items+shipments state at snapshot time.
  snapshot_data_json String

  /// Snapshot record creation timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order shoppingmall_orders @relation(fields: [shoppingmall_order_id], references: [id], onDelete: Cascade)

  @@index([shoppingmall_order_id])
  @@index([snapshot_type])
  @@index([created_at])
}

/// Refund/return payment flows attached to an order and often a sub-order or
/// specific item. Tracks refund amount, payment association, reason, admin
/// handling, and full audit trail for regulatory/compliance. Linked to
/// original payment, refund evidence, and status transitions. Governance for
/// partial/complete refunds, audit recovery, and regulatory SLA compliance.
/// No calculated fields (all values snapped at refund event).
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_order_refunds {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent order {@link shoppingmall_orders.id}.
  shoppingmall_order_id String @db.Uuid

  /// Original payment transaction related to refund {@link
  /// shoppingmall_order_payments.id}.
  shoppingmall_payment_id String @db.Uuid

  /// Unique refund transaction code (business/audit ref).
  refund_code String

  /// Refunded amount for this event as of the snapshot.
  refund_amount Float @db.DoublePrecision

  /// Current refund status (pending, success, failed, cancelled, on_hold,
  /// disputed).
  refund_status String

  /// Reason provided for this refund, business/audit context.
  reason String?

  /// Role requesting refund (customer, seller, admin).
  requested_by_role String

  /// Role processing/approving refund (admin, seller, system).
  processed_by_role String

  /// Timestamp refund was requested/submitted.
  requested_at DateTime @db.Timestamptz

  /// Timestamp processed/approved/denied/failed.
  processed_at DateTime? @db.Timestamptz

  /// Refund record creation timestamp (business audit).
  created_at DateTime @db.Timestamptz

  /// Refund record last updated (audit trail/compliance).
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order shoppingmall_orders @relation(fields: [shoppingmall_order_id], references: [id], onDelete: Cascade)
  payment shoppingmall_order_payments @relation(fields: [shoppingmall_payment_id], references: [id], onDelete: Cascade)

  shoppingmall_order_returns shoppingmall_order_returns[]
  shoppingmall_disputes shoppingmall_disputes[]

  @@unique([refund_code])
  @@index([shoppingmall_order_id])
  @@index([shoppingmall_payment_id])
  @@index([refund_status])
  @@index([requested_by_role])
}

/// Return requests (prior to refund) attached to orders, sub-orders, and
/// items. Contains business logic for eligibility (date, condition), scope,
/// reason, and processing details. Linked to refund flows when approved.
/// Tracks processing/admin roles, evidence, and audit trail for regulatory.
/// Supports multi-item, partial, or complete returns per order. Each return
/// record is uniquely linked to order, items, and refund when approved.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_order_returns {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Order containing the item(s) to return {@link shoppingmall_orders.id}.
  shoppingmall_order_id String @db.Uuid

  /// Refund record created if/when return is approved/paid {@link
  /// shoppingmall_order_refunds.id}.
  shoppingmall_refund_id String? @db.Uuid

  /// Unique return request code for audit/business trace.
  return_code String

  /// Type: full or partial (itemized).
  return_type String

  /// Current status (pending, approved, rejected, cancelled, returned,
  /// completed, failed, on_hold).
  status String

  /// Customer/business reason for initiating return.
  reason String?

  /// JSON array of items and quantities to return (structured for itemized
  /// returns).
  item_list_json String

  /// Who initiated: customer, seller, or admin?
  requested_by_role String

  /// Approver/process role: admin, seller, system.
  processed_by_role String

  /// Return requested timestamp.
  requested_at DateTime @db.Timestamptz

  /// Return processing/approval/denial time.
  processed_at DateTime? @db.Timestamptz

  /// Return record creation time.
  created_at DateTime @db.Timestamptz

  /// Last update to return record.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order shoppingmall_orders @relation(fields: [shoppingmall_order_id], references: [id], onDelete: Cascade)
  refund shoppingmall_order_refunds? @relation(fields: [shoppingmall_refund_id], references: [id], onDelete: Cascade)

  shoppingmall_disputes shoppingmall_disputes[]

  @@unique([return_code])
  @@index([shoppingmall_order_id])
  @@index([shoppingmall_refund_id])
  @@index([status])
}

/// Formal disputes raised regarding order, payment, refund, or delivery.
/// Contains status, subject type, related objects, open/close details,
/// reason, and evidentiary snapshot. Enables compliance and legal handling;
/// supports foreign linkages to refund, return, shipment, and order
/// evidence. Used for regulatory/consumer issues and audit compliance.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_disputes {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Main (root) order subject of dispute {@link shoppingmall_orders.id}.
  shoppingmall_order_id String @db.Uuid

  /// Refund in dispute if applicable {@link shoppingmall_order_refunds.id}.
  shoppingmall_refund_id String? @db.Uuid

  /// Return in dispute if applicable {@link shoppingmall_order_returns.id}.
  shoppingmall_return_id String? @db.Uuid

  /// Shipment/fulfillment in dispute if applicable {@link
  /// shoppingmall_order_shipments.id}.
  shoppingmall_shipment_id String? @db.Uuid

  /// Globally unique dispute identifier for audit.
  dispute_code String

  /// Nature of dispute (order, refund, return, shipment, product, etc.).
  dispute_type String

  /// Status (pending, open, resolved, rejected, cancelled, escalated, on_hold,
  /// closed).
  status String

  /// Role that initiated dispute (customer, seller, admin).
  opened_by_role String

  /// Dispute case opened time.
  opened_at DateTime @db.Timestamptz

  /// Role closing the dispute (admin, seller, customer, system).
  closed_by_role String?

  /// Case closed time (if resolved or rejected).
  closed_at DateTime? @db.Timestamptz

  /// JSON snapshot of disputed object context (order, payment, refund,
  /// delivery, product).
  dispute_subject_json String

  /// JSON narrative/structure of how dispute was settled (compliance/legal
  /// trace).
  resolution_summary_json String?

  /// Dispute record creation (audit).
  created_at DateTime @db.Timestamptz

  /// Last update to dispute record.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order shoppingmall_orders @relation(fields: [shoppingmall_order_id], references: [id], onDelete: Cascade)
  refund shoppingmall_order_refunds? @relation(fields: [shoppingmall_refund_id], references: [id], onDelete: Cascade)
  return shoppingmall_order_returns? @relation(fields: [shoppingmall_return_id], references: [id], onDelete: Cascade)
  shipment shoppingmall_order_shipments? @relation(fields: [shoppingmall_shipment_id], references: [id], onDelete: Cascade)

  @@unique([dispute_code])
  @@index([shoppingmall_order_id])
  @@index([shoppingmall_refund_id])
  @@index([shoppingmall_return_id])
  @@index([shoppingmall_shipment_id])
  @@index([status])
}

/// Evidence and audit-trail linkage table for all order-related compliance
/// events (creation, update, refund, dispute, return, shipment). Records
/// event, type, business context, actor, and snapshot. Enables full
/// traceability for legal, SLA, or regulatory requirements. Supports
/// bulk/batch download for legal hold or regulatory export.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_order_evidence {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Order this evidence is bound to {@link shoppingmall_orders.id}.
  shoppingmall_order_id String @db.Uuid

  /// Actor (user, seller, admin) who created this evidence (links to
  /// audit/compliance user profile) {@link shoppingmall_actor_profiles.id}.
  shoppingmall_actor_id String? @db.Uuid

  /// Nature/type: creation, payment_submit, payment_complete, shipment,
  /// delivery, refund, return, dispute, cancellation, compliance, system, etc.
  evidence_type String

  /// Serialized JSON of the business context for evidence (order, payment,
  /// reason, files, etc.).
  evidence_context_json String

  /// Evidence record creation time.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order shoppingmall_orders @relation(fields: [shoppingmall_order_id], references: [id], onDelete: Cascade)
  actor shoppingmall_actor_profiles? @relation(fields: [shoppingmall_actor_id], references: [id], onDelete: Cascade)

  @@index([shoppingmall_actor_id])

  @@index([shoppingmall_order_id])
  @@index([evidence_type])
  @@index([created_at])
}

schemas.schema-06-coupons.prisma:
/// Defines the master templates for coupons, including rules for benefit
/// calculation, eligibility, allowed stacking, redemption windows, and
/// associated metadata. This table structures business logic applicable to
/// batches of issued coupons and supports both platform (admin) and
/// seller-originated campaigns. Supports audit trails for retroactive policy
/// changes and analytics for benefit optimization.
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_coupon_templates {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Admin's {@link shoppingmall_admins.id} who created this coupon template.
  created_by_admin_id String? @db.Uuid

  /// Seller's {@link shoppingmall_sellers.id} who created this coupon template
  /// (nullable if admin-created).
  created_by_seller_id String? @db.Uuid

  /// Type of coupon: one of fixed_amount, percentage, free_shipping, etc. Used
  /// for determining benefit calculation logic.
  type String

  /// Business-facing name of the coupon template.
  name String

  /// Long-form business description for the template, explaining business
  /// context, user eligibility, and restriction rules.
  description String?

  /// Window start timestamp when coupons based on this template become valid
  /// for redemption.
  start_at DateTime @db.Timestamptz

  /// Window end timestamp after which no more coupons from this template can
  /// be issued or redeemed.
  end_at DateTime @db.Timestamptz

  /// Business rule: minimum order amount required to enable coupon usage (if
  /// applicable).
  min_order_amount Float? @db.DoublePrecision

  /// Maximum discount amount allowed for this template, used to cap value in
  /// percent-based or stackable offers.
  max_discount_amount Float? @db.DoublePrecision

  /// Total number of coupons issued from this template.
  issued_quantity Int @db.Integer

  /// Maximum number of times a single user can redeem coupons from this
  /// template.
  allowed_uses_per_user Int @db.Integer

  /// Indicates whether coupons using this template can be stacked (combined)
  /// with others in a single order.
  combinable Boolean

  /// Shows if the template is currently active (no subsequent issuance if
  /// false).
  active Boolean

  /// Business extensibility field for extra metadata (JSON encoded for
  /// flexible business logic).
  metadata_json String?

  /// Template creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last template modification timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft-deletion timestamp, null until business removal required.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  createdByAdmin shoppingmall_admins? @relation(fields: [created_by_admin_id], references: [id], onDelete: Cascade)
  createdBySeller shoppingmall_sellers? @relation(fields: [created_by_seller_id], references: [id], onDelete: Cascade)

  shoppingmall_coupons shoppingmall_coupons[]

  @@index([created_by_admin_id])
  @@index([created_by_seller_id])

  @@unique([name])
  @@index([type])
  @@index([start_at, end_at])
}

/// Represents individual coupons issued to the platform or sellers,
/// inheriting rules from the template table. Tracks coupon code, assignment,
/// status, and base eligibility parameters (e.g., target user, valid window,
/// original value).
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_coupons {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Originating template's {@link shoppingmall_coupon_templates.id}.
  coupon_template_id String @db.Uuid

  /// Globally unique code or identifier for the coupon (redeemable by user at
  /// checkout).
  coupon_code String

  /// Customer's {@link shoppingmall_customers.id} this coupon is assigned to
  /// (nullable until claimed or issued).
  assigned_to_customer_id String? @db.Uuid

  /// Seller's {@link shoppingmall_sellers.id} if coupon is restricted to a
  /// specific seller (nullable if platform-wide).
  issued_to_seller_id String? @db.Uuid

  /// Timestamp when this coupon was issued to user or made available for claim.
  issued_at DateTime @db.Timestamptz

  /// Business expiry date for this coupon (cannot be redeemed after this point
  /// even if template valid).
  expires_at DateTime @db.Timestamptz

  /// State flag indicating if coupon has been redeemed at least once.
  redeemed Boolean

  /// If true, this coupon is temporarily or permanently locked by
  /// business/validation rules (e.g., fraud, dispute, compliance).
  locked Boolean

  /// Business extensibility: optional JSON for assigning additional metadata,
  /// campaign info, or error traces.
  metadata_json String?

  /// Coupon creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Coupon last updated timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft-deletion timestamp, null unless business removal required.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  template shoppingmall_coupon_templates @relation(fields: [coupon_template_id], references: [id], onDelete: Cascade)

  shoppingmall_coupon_issuances shoppingmall_coupon_issuances?
  shoppingmall_coupon_redemptions shoppingmall_coupon_redemptions[]
  shoppingmall_coupon_errors shoppingmall_coupon_errors[]

  @@index([coupon_template_id])

  @@unique([coupon_code])
  @@index([assigned_to_customer_id])
  @@index([issued_to_seller_id])
}

/// Tracks every coupon issued from a template, identifying the actor (admin
/// or seller), time, method (bulk, direct, user-claim), and context. This
/// model is used for benefit auditing and campaign analytics.
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_coupon_issuances {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Issued coupon's {@link shoppingmall_coupons.id}.
  coupon_id String @db.Uuid

  /// Admin's {@link shoppingmall_admins.id} who issued the coupon (if
  /// admin-driven).
  issued_by_admin_id String? @db.Uuid

  /// Seller's {@link shoppingmall_sellers.id} if coupon issued by seller, null
  /// if platform-only.
  issued_by_seller_id String? @db.Uuid

  /// Describes business method of issuance: e.g., 'direct_assign',
  /// 'bulk_event', 'self_claimed', etc.
  issue_method String

  /// Additional business context of issuance (trigger event, segmentation,
  /// batch info, etc.), JSON encoded.
  context_json String?

  /// Timestamp when this issuance was created.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  coupon shoppingmall_coupons @relation(fields: [coupon_id], references: [id], onDelete: Cascade)
  issuedByAdmin shoppingmall_admins? @relation(fields: [issued_by_admin_id], references: [id], onDelete: Cascade)
  issuedBySeller shoppingmall_sellers? @relation(fields: [issued_by_seller_id], references: [id], onDelete: Cascade)

  @@index([issued_by_admin_id])
  @@index([issued_by_seller_id])

  @@unique([coupon_id])
}

/// Records each redemption event for coupons. Links coupon, redeemer
/// (customer), redemption context, result, and timestamps. Used for
/// enforcement of benefit usage rules and benefit dispute evidence.
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_coupon_redemptions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Coupon's {@link shoppingmall_coupons.id} being redeemed.
  coupon_id String @db.Uuid

  /// Customer's {@link shoppingmall_customers.id} who redeemed the coupon.
  redeemed_by_customer_id String @db.Uuid

  /// Order's {@link shoppingmall_orders.id} where coupon was used (if known at
  /// time of redemption).
  order_id String? @db.Uuid

  /// Amount of benefit redeemed (currency value for discount or actual value
  /// of benefit).
  benefit_amount Float @db.DoublePrecision

  /// Outcome/result status of redemption: e.g., 'success', 'failed_minimum',
  /// 'expired', 'disputed'.
  redemption_result String

  /// Business context for redemption (e.g., reasoning, cart snapshot), JSON
  /// encoded.
  redemption_context_json String?

  /// Redemption event timestamp.
  redeemed_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  coupon shoppingmall_coupons @relation(fields: [coupon_id], references: [id], onDelete: Cascade)
  redeemedByCustomer shoppingmall_customers @relation(fields: [redeemed_by_customer_id], references: [id], onDelete: Cascade)

  @@index([redeemed_by_customer_id])

  @@index([coupon_id])
}

/// Records all mileage (loyalty point) accruals and deductions for
/// users—including initial award, promotional boosters, redemptions,
/// expirations, reversals, and admin/seller/manual adjustments. Supports
/// full auditability by point origin, value, event, and status.
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_mileage_ledger {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer's {@link shoppingmall_customers.id} who owns this ledger record.
  customer_id String @db.Uuid

  /// Admin's {@link shoppingmall_admins.id} who performed manual mileage
  /// adjustment (nullable if system-driven).
  admin_id String? @db.Uuid

  /// Seller's {@link shoppingmall_sellers.id} who performed mileage adjustment
  /// (nullable if not seller-driven event).
  seller_id String? @db.Uuid

  /// Describes the business event: e.g.,
  /// 'order_award','coupon_bonus','redemption','expiration','manual_adjustment'.
  event_type String

  /// Number of points accrued (+) or deducted (-) from user's balance in this
  /// event.
  mileage_delta Float @db.DoublePrecision

  /// Order's {@link shoppingmall_orders.id} linked to this mileage event (null
  /// if not order-related).
  related_order_id String? @db.Uuid

  /// Free-form admin or business-facing notes, e.g., explanation for manual
  /// adjustment or error context.
  notes String?

  /// Mileage event creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Timestamp when mileage expires (null if not expired or not per-point
  /// expiry model).
  expired_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shoppingmall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  admin shoppingmall_admins? @relation(fields: [admin_id], references: [id], onDelete: Cascade)
  seller shoppingmall_sellers? @relation(fields: [seller_id], references: [id], onDelete: Cascade)

  @@index([admin_id])
  @@index([seller_id])

  @@index([customer_id])
  @@index([event_type])
}

/// Tracks all deposit balance-related activities for a user, including
/// top-ups, deductions for orders, refunds, expiration, and provider-based
/// adjustments. Supports full business/audit trace from original event to
/// each impact on the user's account.
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_deposit_ledger {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer's {@link shoppingmall_customers.id} whose deposit balance is
  /// impacted.
  customer_id String @db.Uuid

  /// Admin's {@link shoppingmall_admins.id} performing deposit action (if not
  /// system-driven).
  admin_id String? @db.Uuid

  /// Describes the deposit business event: e.g.,
  /// 'topup','order_payment','refund', 'expiration','manual_adjustment'.
  event_type String

  /// Deposited (+) or deducted (-) amount of funds (platform currency units).
  amount_delta Float @db.DoublePrecision

  /// Order's {@link shoppingmall_orders.id} if event is related to an order
  /// transaction.
  related_order_id String? @db.Uuid

  /// Payment provider identifier (e.g.,
  /// 'credit_card','bank_transfer','voucher', etc.).
  provider String?

  /// Admin or system notes for business/audit/exception context.
  notes String?

  /// Deposit event creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Timestamp when deposit expires (if per-transaction expiration/policy
  /// applies).
  expired_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shoppingmall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  admin shoppingmall_admins? @relation(fields: [admin_id], references: [id], onDelete: Cascade)

  @@index([admin_id])

  @@index([customer_id])
  @@index([event_type])
}

/// Historical business snapshots of user benefit entitlements at the time of
/// issuance, redemption, or adjustment—used for compliance, disputes, legal
/// evidence, and retroactive benefit restoration. Stores point-in-time,
/// immutable business records for every coupon, mileage, or deposit event.
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_benefit_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer's {@link shoppingmall_customers.id} whose benefit entitlement is
  /// snapshotted.
  customer_id String @db.Uuid

  /// Type of benefit at snapshot: 'coupon', 'mileage', or 'deposit'.
  benefit_type String

  /// ID of the source entity (coupon_id, mileage_ledger_id, or
  /// deposit_ledger_id as applicable).
  source_id String @db.Uuid

  /// Full snapshot of business state and entitlements at point-in-time (JSON
  /// encoded).
  snapshot_json String

  /// Triggering event: 'issuance', 'redemption', 'adjustment', 'expiration',
  /// 'rollback', etc.
  event_type String

  /// Snapshot creation timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shoppingmall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  shoppingmall_benefit_audit shoppingmall_benefit_audit[]

  @@index([customer_id])
  @@index([benefit_type])
}

/// Immutable, tamper-evident audit log for all benefit (coupon, mileage,
/// deposit) events, including issuance, redemption, expiration, failure, and
/// business corrections. Critical for compliance, business rule enforcement,
/// and regulatory retrieval.
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_benefit_audit {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Source entity for audit (may refer to coupon, mileage, or deposit entry).
  source_id String? @db.Uuid

  /// Customer's {@link shoppingmall_customers.id} whose benefit action is
  /// being audited.
  customer_id String @db.Uuid

  /// Type of benefit impacted: 'coupon', 'mileage', or 'deposit'.
  benefit_type String

  /// Business event: 'issuance',
  /// 'redemption','expiration','manual_correction','auto_expire', 'dispute',
  /// etc.
  event_type String

  /// Business context or metadata for this event (JSON encoded).
  event_context_json String?

  /// Audit event creation timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  source shoppingmall_benefit_snapshots? @relation(fields: [source_id], references: [id], onDelete: Cascade)
  customer shoppingmall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  @@index([source_id])

  @@index([customer_id])
  @@index([benefit_type])
  @@index([event_type])
}

/// Represents business, eligibility, validation, and redemption errors
/// related to coupon usage. Used to improve user experience, root cause
/// analysis, and business policy refinement. Supports both user-facing and
/// internal error reporting.
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_coupon_errors {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Coupon's {@link shoppingmall_coupons.id} related to this error event.
  coupon_id String @db.Uuid

  /// Customer's {@link shoppingmall_customers.id} affected by this error
  /// occurrence.
  customer_id String? @db.Uuid

  /// Application/business error code (e.g., 'COUPON_EXPIRED',
  /// 'COUPON_INELIGIBLE').
  error_code String

  /// User-facing or system error message explaining cause and suggested
  /// remediation.
  error_message String

  /// Optional serialized business context for error (JSON encoded).
  business_context_json String?

  /// Error event occurrence timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  coupon shoppingmall_coupons @relation(fields: [coupon_id], references: [id], onDelete: Cascade)
  customer shoppingmall_customers? @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  @@index([customer_id])

  @@index([coupon_id])
  @@index([error_code])
}

schemas.schema-07-articles.prisma:
/// Business articles and editorial posts for the shoppingMall community and
/// platform. Managed by admins or authorized sellers, these support platform
/// news, guides, major updates, editorial content, and feature rollouts.
/// Audience is customers and sellers. Threaded comments, content snapshots,
/// and compliance audit tracked via related models. Subject to moderation,
/// reporting, and analytics through related entities.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_articles {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Actor's {@link shoppingmall_actor_profiles.id} who created the article.
  created_by_id String @db.Uuid

  /// Article title. Shown in listings, SEO, and notifications.
  title String

  /// Full published content of the article. May include rich formatting.
  body String

  /// Short summary for preview or search result snippets. Typically 100-300
  /// chars.
  summary String?

  /// Cover image for this article, used in lists and previews. Must be a valid
  /// image URI or file reference.
  cover_image_uri String? @db.VarChar(80000)

  /// Whether this article is currently pinned at the top of listing pages or
  /// dashboards. Admin only.
  pinned Boolean

  /// Datetime article was made public. Null if draft or pending.
  published_at DateTime? @db.Timestamptz

  /// Datetime of initial article creation. Immutable, for evidence and audit.
  created_at DateTime @db.Timestamptz

  /// Datetime of most recent edit. For audit and dashboard display.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion flag. Set when logically deleted, retained for compliance
  /// and evidence.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  createdBy shoppingmall_actor_profiles @relation(fields: [created_by_id], references: [id], onDelete: Cascade)

  shoppingmall_inquiries shoppingmall_inquiries[]
  shoppingmall_reported_content shoppingmall_reported_content[]
  shoppingmall_content_flags shoppingmall_content_flags[]

  @@unique([title, created_by_id])
  @@index([created_by_id])
  @@index([published_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Threaded comments for UGC articles, inquiries, reviews, or bulletins.
/// Supports nested replies via parent-child hierarchy. Moderation,
/// reporting, evidence, and analytics handled by related models. Each
/// comment links to content target, owning actor, and may be soft-deleted.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_comments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Self-referential. The parent comment's {@link shoppingmall_comments.id},
  /// for nested comment threads.
  parent_id String? @db.Uuid

  /// The root thread's {@link shoppingmall_thread_statistics.id} this comment
  /// belongs to, grouping all comments for a single content object.
  thread_id String @db.Uuid

  /// Actor's {@link shoppingmall_actor_profiles.id} who posted the comment.
  author_id String @db.Uuid

  /// Comment message content. Plain text or optionally formatted by policy.
  body String

  /// Whether this comment has been edited after initial submission. Used for
  /// audit and display.
  edited Boolean

  /// Datetime when comment was first created. Immutable.
  created_at DateTime @db.Timestamptz

  /// Datetime when comment was last edited. Changes if edited=true.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion field. Null unless deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  parent shoppingmall_comments? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)
  thread shoppingmall_thread_statistics @relation(fields: [thread_id], references: [id], onDelete: Cascade)
  author shoppingmall_actor_profiles @relation(fields: [author_id], references: [id], onDelete: Cascade)

  recursive shoppingmall_comments[] @relation("recursive")
  shoppingmall_reported_content shoppingmall_reported_content[]
  shoppingmall_content_flags shoppingmall_content_flags[]

  @@index([thread_id])
  @@index([author_id])
  @@index([parent_id])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Product, service, or bulletin Q&A inquiries initiated by authenticated
/// users. Each inquiry is linked to a product, article, or bulletin (via
/// foreign key or thread linkage), supports status tracking, moderation, and
/// evidence/audit via snapshots. Answers are managed in separate table.
/// Reporting, flagging, and compliance handled via related entities.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_inquiries {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The root thread's {@link shoppingmall_thread_statistics.id} for this
  /// inquiry (groups all posts: Q&A, comments, stats, etc.).
  thread_id String @db.Uuid

  /// Inquiry by customer's {@link shoppingmall_customers.id}.
  customer_id String @db.Uuid

  /// Target product's {@link shoppingmall_products.id} (if product inquiry).
  target_product_id String? @db.Uuid

  /// Target article's {@link shoppingmall_articles.id} (if article inquiry).
  target_article_id String? @db.Uuid

  /// Target bulletin's {@link shoppingmall_bulletins.id} (if bulletin inquiry).
  target_bulletin_id String? @db.Uuid

  /// Full inquiry question submitted by user. Subject to profanity check,
  /// validation. Min 10, max 1000 characters.
  question String

  /// Business status code of inquiry: pending, answered, closed, or escalated,
  /// per business rules.
  status String

  /// Datetime of inquiry submission. Immutable, for evidence and search.
  created_at DateTime @db.Timestamptz

  /// Datetime of most recent inquiry update or status change.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion. Set when logically removed for compliance, evidence, or
  /// policy.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  thread shoppingmall_thread_statistics @relation(fields: [thread_id], references: [id], onDelete: Cascade)
  customer shoppingmall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  product shoppingmall_products? @relation(fields: [target_product_id], references: [id], onDelete: Cascade)
  article shoppingmall_articles? @relation(fields: [target_article_id], references: [id], onDelete: Cascade)
  bulletin shoppingmall_bulletins? @relation(fields: [target_bulletin_id], references: [id], onDelete: Cascade)

  shoppingmall_inquiry_answers shoppingmall_inquiry_answers?
  shoppingmall_reported_content shoppingmall_reported_content[]
  shoppingmall_content_flags shoppingmall_content_flags[]
  shoppingmall_favorite_inquiries shoppingmall_favorite_inquiries[]

  @@index([target_product_id])
  @@index([target_article_id])
  @@index([target_bulletin_id])

  @@unique([question, customer_id, created_at])
  @@index([thread_id])
  @@index([customer_id])
  @@index([status])
  @@index([question(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Official answers (from seller or admin) to inquiries. Answers are 1:1
/// with inquiries but may support edits and history (tracked by snapshots).
/// Clearly associated to responding actor, with audit and compliance
/// requirements. Used for business/role escalation workflows.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_inquiry_answers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Target inquiry's {@link shoppingmall_inquiries.id} being answered.
  inquiry_id String @db.Uuid

  /// Actor's {@link shoppingmall_actor_profiles.id} who responded. Must be
  /// seller or admin.
  responder_id String @db.Uuid

  /// Answer message content. May support rich text or formatting depending on
  /// business logic.
  body String

  /// Whether this answer has been edited after initial submission. Used for
  /// audit purposes.
  edited Boolean

  /// Datetime when answer was first created. Immutable.
  created_at DateTime @db.Timestamptz

  /// Datetime when answer was last edited. Changes if edited=true.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion field. Set when answer removed logically, retained for
  /// audit.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  inquiry shoppingmall_inquiries @relation(fields: [inquiry_id], references: [id], onDelete: Cascade)
  responder shoppingmall_actor_profiles @relation(fields: [responder_id], references: [id], onDelete: Cascade)

  shoppingmall_favorite_inquiries shoppingmall_favorite_inquiries[]

  @@unique([inquiry_id])

  @@index([inquiry_id])
  @@index([responder_id])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Product, service, or seller reviews entered by customers after
/// purchase/fulfillment. Each review links to a thread, the reviewed entity
/// (product or seller), and the submitting customer. Supported features:
/// star rating, text content, optional media, moderation, reporting, and
/// analytics. Review edits and compliance evidence retained via snapshots.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_reviews {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The root thread's {@link shoppingmall_thread_statistics.id} for this
  /// review and all replies/posts.
  thread_id String @db.Uuid

  /// Authoring customer's {@link shoppingmall_customers.id}.
  customer_id String @db.Uuid

  /// Reviewed product's {@link shoppingmall_products.id}. Null if not a
  /// product review.
  target_product_id String? @db.Uuid

  /// Reviewed seller's {@link shoppingmall_sellers.id}. Null if not seller
  /// review.
  target_seller_id String? @db.Uuid

  /// Business review score. 1 to 5 stars, inclusive. Enforced by validation
  /// logic.
  rating Int @db.Integer

  /// Short review title, used in lists or search. Optional.
  title String?

  /// Review content body. Min 10, max 2000 characters. Must pass validation
  /// and moderation.
  body String

  /// Indicates if review is from a verified purchase/order (for business trust
  /// badge display).
  verified_purchase Boolean

  /// Datetime of review submission. Immutable, for time-based sort or evidence.
  created_at DateTime @db.Timestamptz

  /// Datetime of most recent review update (body, title, etc).
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp, if removed logically for policy/compliance.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  thread shoppingmall_thread_statistics @relation(fields: [thread_id], references: [id], onDelete: Cascade)
  customer shoppingmall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  product shoppingmall_products? @relation(fields: [target_product_id], references: [id], onDelete: Cascade)
  seller shoppingmall_sellers? @relation(fields: [target_seller_id], references: [id], onDelete: Cascade)

  shoppingmall_review_replies shoppingmall_review_replies?
  shoppingmall_reported_content shoppingmall_reported_content[]
  shoppingmall_content_flags shoppingmall_content_flags[]

  @@unique([thread_id, customer_id, target_product_id], map: "shoppingmall_reviews_thread_id_customer_id_target_prod_518603d3")
  @@unique([thread_id, customer_id, target_seller_id])
  @@index([thread_id])
  @@index([customer_id])
  @@index([target_product_id])
  @@index([target_seller_id])
  @@index([rating])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Authoritative replies to reviews from sellers or admins. One reply per
/// review. Replies support moderation, edits, evidence/audit, and can be
/// flagged for abuse. Each is associated to a review and responding actor
/// role.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_review_replies {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Target review's {@link shoppingmall_reviews.id} being replied to.
  review_id String @db.Uuid

  /// Actor's {@link shoppingmall_actor_profiles.id} replying to the review.
  /// Usually a seller or admin.
  responder_id String @db.Uuid

  /// Reply message content, including moderation notes or acknowledgments.
  body String

  /// Whether this reply has been edited after submission. Required for
  /// evidence and audit.
  edited Boolean

  /// Creation datetime of review reply. Immutable.
  created_at DateTime @db.Timestamptz

  /// Datetime of most recent edit to reply.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion flag. Set when reply logically deleted (policy/compliance).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  review shoppingmall_reviews @relation(fields: [review_id], references: [id], onDelete: Cascade)
  responder shoppingmall_actor_profiles @relation(fields: [responder_id], references: [id], onDelete: Cascade)

  @@unique([review_id])

  @@index([review_id])
  @@index([responder_id])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Bulletin board posts and platform-wide announcements. Created mainly by
/// admins but can be posted by designated sellers for community marketing,
/// legal, or major campaign notices. Supports pinning, expiration, and
/// visibility logic. Audit and content evidence preserved for compliance
/// uses. Comments and reporting supported via related models.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_bulletins {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Actor's {@link shoppingmall_actor_profiles.id} who posted the bulletin
  /// (admin or seller).
  author_id String @db.Uuid

  /// Bulletin headline or title. Used for listings, links, and notifications.
  title String

  /// Bulletin message content. Can include formatting, images, or legal text.
  body String

  /// If the bulletin is currently pinned at the top of listings. Admin only.
  pinned Boolean

  /// Visibility policy: all, customers, sellers, or admin-only. Used to
  /// restrict who sees a post.
  visible_to String

  /// Optional expiration; bulletin hidden after this date for users.
  expire_at DateTime? @db.Timestamptz

  /// Datetime of creation. Immutable, for evidence and compliance.
  created_at DateTime @db.Timestamptz

  /// Datetime of last edit or update. Tracked for moderation/audit.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion. Set when logically removed, but still retained for
  /// compliance period.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  author shoppingmall_actor_profiles @relation(fields: [author_id], references: [id], onDelete: Cascade)

  shoppingmall_inquiries shoppingmall_inquiries[]
  shoppingmall_reported_content shoppingmall_reported_content[]
  shoppingmall_content_flags shoppingmall_content_flags[]

  @@unique([title, created_at])
  @@index([author_id])
  @@index([pinned])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Business-level content abuse or violation reports filed by users or
/// detected by automated systems. Supports multi-type (comment, review,
/// bulletin, article, etc.) targeting, links to reporting actor, management
/// status, and audit evidence. Used for moderation, compliance, and
