/// Immutable audit log for all lifecycle changes to attachments. Captures
/// who, when, what action, and context for every mutation (upload, replace,
/// delete, quarantine, restore, legal hold, etc.). Used to ensure evidence
/// in compliance and legal investigations. Each entry is a permanent record.
///
/// @namespace Attachments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_attachment_audit {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Attachment affected by this audit event. {@link
  /// shoppingmall_attachments.id}
  attachment_id String @db.Uuid

  /// User/admin who performed the action.
  actor_user_id String @db.Uuid

  /// Type of action: upload, delete, restore, quarantine, legal_hold, replace,
  /// update_metadata, etc.
  action_type String

  /// JSON or human-readable context for the action (reason, details, IP, etc.).
  action_context String

  /// Immutable timestamp for when the audit entry was created.
