///
/// @namespace Attachments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_attachment_quarantine {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Attachment under quarantine. {@link shoppingmall_attachments.id}
