  release_context String?

  //----
  // RELATIONS
  //----
  attachment shoppingmall_attachments @relation(fields: [attachment_id], references: [id], onDelete: Cascade)

  @@unique([attachment_id])
}

/// Records appeals lodged by users or sellers against attachment quarantine,
/// moderation, or removal actions. Supports the compliance
/// remediation/review process. Each record is a remediation request or
/// appeal and its resolution.
///
/// @namespace Attachments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_attachment_appeals {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Attachment that is subject to the appeal process. {@link
  /// shoppingmall_attachments.id}
  attachment_id String @db.Uuid

  /// User (typically owner) initiating the appeal.
  appealing_user_id String @db.Uuid

  /// Business/message for the appeal. User-provided context.
