  /// Human/log note for outcome, including business/legal rationale.
  resolution_message String?

  /// Resolution time if resolved.
  resolution_timestamp DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  attachment shoppingmall_attachments @relation(fields: [attachment_id], references: [id], onDelete: Cascade)

  @@index([attachment_id])
  @@index([appealing_user_id])
}

/// Tracks active retention/expiry policies applied to each attachment for
/// compliance, legal, and business obligations. Maintains when a file
/// expires per rule, who configured policy, and critical event logs.
/// Guarantees files are managed as per contract, law, or internal policy.
///
/// @namespace Attachments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_attachment_retention {
  //----
  // COLUMNS
