  /// When this retention record was created.
  created_at DateTime @db.Timestamptz

  /// Last updated time.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  attachment shoppingmall_attachments @relation(fields: [attachment_id], references: [id], onDelete: Cascade)

  @@unique([attachment_id])
}

/// Records technical/business/security incidents involving attachments:
