  /// User or admin who triggered/logged the incident.
  actor_user_id String @db.Uuid

  /// When the incident was detected or logged.
  incident_timestamp DateTime @db.Timestamptz

  /// Outcome/status: open, closed, escalated, resolved, pending, etc.
