schemas.schema-10-business.prisma:
/// Catalog of universal business rules, constraints, and policies enforced
/// platform-wide. Allows for dynamic rule management, audit, and rapid
/// update across the system. Relationships include rule assignments to
/// entities and audit trails for changes. Not tied to transactional records;
/// only stores the authoritative definition, scope, and core logic metadata.
///
/// @namespace BusinessRules
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_business_rules {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique business rule code identifier (e.g., BR-1001). Used for
  /// referencing in assignments and audit logs.
  code String

  /// Human-readable name of the business rule.
  title String

  /// Detailed narrative/business context of the rule for documentation and
  /// compliance reporting.
  description String

  /// The scope of applicability (e.g., 'order', 'product', 'payment', or
  /// global).
  rule_scope String

  /// Whether the rule is currently active and enforced.
  active Boolean

  /// Relative enforcement priority: lower is higher priority. Used for
  /// sequencing validation.
  priority Int @db.Integer

  /// Rule creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp; null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  shoppingmall_rule_assignments shoppingmall_rule_assignments[]
  shoppingmall_rule_applications shoppingmall_rule_applications[]
  shoppingmall_regulatory_mappings shoppingmall_regulatory_mappings[]
  shoppingmall_rules_audit shoppingmall_rules_audit[]

  @@unique([code])
  @@index([rule_scope])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Assignments linking business rules to specific objects/entities (e.g.,
/// product, order, user). Enables dynamic rule targeting, compliance
/// validation, and context-scoped enforcement.
///
/// @namespace BusinessRules
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_rule_assignments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Target business rule's {@link shoppingmall_business_rules.id}.
  shoppingmall_business_rule_id String @db.Uuid

  /// Entity type this assignment refers to (e.g., 'order', 'product', 'user',
  /// etc.).
  target_type String

  /// UUID of the specific object/entity being targeted for rule assignment.
  target_id String @db.Uuid

  /// Contextual marker (e.g., channel or regional scope) for assignment;
  /// supports multi-context rules.
  applied_context String?

  /// Assignment creation timestamp.
  assigned_at DateTime @db.Timestamptz

  /// Assignment expiration timestamp (null if ongoing/active).
  expired_at DateTime? @db.Timestamptz

  /// Timestamp of assignment record creation.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for assignment.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  businessRule shoppingmall_business_rules @relation(fields: [shoppingmall_business_rule_id], references: [id], onDelete: Cascade, map: "shoppingmall_rule_assignments_shoppingmall_business_ru_c31578b0")

  shoppingmall_rule_applications shoppingmall_rule_applications[]

  @@unique([shoppingmall_business_rule_id, target_type, target_id, applied_context], map: "shoppingmall_rule_assignments_shoppingmall_business_ru_cdd17087")
  @@index([target_type, target_id])
}

/// Tracks the application of a business rule to a specific context or event,
/// including pass/fail and evidence references. Used for compliance proof
/// and auditability of rule logic execution.
///
/// @namespace BusinessRules
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_rule_applications {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Applied rule's {@link shoppingmall_business_rules.id}.
  shoppingmall_business_rule_id String @db.Uuid

  /// Target rule assignment's {@link shoppingmall_rule_assignments.id}.
  shoppingmall_rule_assignment_id String @db.Uuid

  /// Narrative/context in which the rule was applied (e.g., 'order_checkout',
  /// 'payment_refund').
  application_context String

  /// Timestamp when rule was applied.
  triggered_at DateTime @db.Timestamptz

  /// True if the rule passed; false if it was violated.
  passed Boolean

  /// Reference to evidence supporting this application (links to
  /// shoppingmall_evidence_bundles.id).
  evidence_bundle_id String? @db.Uuid

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Record update timestamp.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  businessRule shoppingmall_business_rules @relation(fields: [shoppingmall_business_rule_id], references: [id], onDelete: Cascade, map: "shoppingmall_rule_applications_shoppingmall_business_r_89dc4ca7")
  ruleAssignment shoppingmall_rule_assignments @relation(fields: [shoppingmall_rule_assignment_id], references: [id], onDelete: Cascade, map: "shoppingmall_rule_applications_shoppingmall_rule_assig_b70b0c5d")

  @@index([shoppingmall_business_rule_id], map: "shoppingmall_rule_applications_shoppingmall_business_r_3d9b57c8")
  @@index([shoppingmall_rule_assignment_id], map: "shoppingmall_rule_applications_shoppingmall_rule_assig_dff35bea")

  @@index([application_context])
}

/// Catalog and record of validation error codes and messages returned by
/// rule engine/application logic. Used for traceability, developer
/// reference, and compliance error reporting/auditing.
///
/// @namespace BusinessRules
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_validation_errors {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique validation error code (e.g. ERR_MIN_VALUE, ORDER_NOT_FOUND).
