  message String

  /// Link to documentation or knowledge base entry explaining the error code.
  documentation_uri String? @db.VarChar(80000)

  /// Business-defined severity level (e.g. info, warning, error, critical).
  severity String

  /// Whether this error has been deprecated or replaced in business flows.
  deprecated Boolean

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp; null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([error_code])
  @@index([message(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Stores hashes, digital signatures, file references, and context for
/// evidence collected during rule application, audit, or compliance
/// investigation. Central to demonstrating regulatory and legal compliance;
/// supports linking to external object storage.
///
/// @namespace BusinessRules
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_evidence_bundles {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique hash/digest representing this evidence bundle (e.g., SHA256).
  bundle_hash String

  /// Narrative describing evidence context, purpose, or chain of custody.
  description String

  /// Optional URI to external evidence file or system (e.g., S3, Azure Blob).
  external_reference_uri String? @db.VarChar(80000)

  /// Actor (user/admin/service) that collected or submitted the evidence.
  created_by_actor_id String @db.Uuid

  /// Evidence creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Record update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp; null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  shoppingmall_legal_holds shoppingmall_legal_holds[]
  shoppingmall_compliance_events shoppingmall_compliance_events[]
  shoppingmall_incident_reports shoppingmall_incident_reports[]

  @@unique([bundle_hash])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Represents business records under legal or regulatory hold, preventing
/// deletion/modification pending investigation or compliance actions.
/// References evidence bundles and target objects bound by hold.
///
/// @namespace BusinessRules
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_legal_holds {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Linked evidence bundle's {@link shoppingmall_evidence_bundles.id}.
  evidence_bundle_id String @db.Uuid

  /// Type of object under legal hold (e.g., 'order', 'product', 'user', etc.).
