  /// Update timestamp.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  businessRule shoppingmall_business_rules @relation(fields: [shoppingmall_business_rule_id], references: [id], onDelete: Cascade, map: "shoppingmall_regulatory_mappings_shoppingmall_business_b624077b")

  @@unique([shoppingmall_business_rule_id, regime_code, jurisdiction], map: "shoppingmall_regulatory_mappings_shoppingmall_business_5fe132cb")
  @@index([jurisdiction])
}

/// Record of compliance-related events, such as audits, regulatory
