  shoppingmall_order_status_logs      shoppingmall_order_status_logs[]
  shoppingmall_order_evidence         shoppingmall_order_evidence[]
  shoppingmall_articles               shoppingmall_articles[]
  shoppingmall_comments               shoppingmall_comments[]
  shoppingmall_inquiry_answers        shoppingmall_inquiry_answers[]
  shoppingmall_review_replies         shoppingmall_review_replies[]
  shoppingmall_bulletins              shoppingmall_bulletins[]
  shoppingmall_reported_content       shoppingmall_reported_content[]
  shoppingmall_content_flags          shoppingmall_content_flags[]
  shoppingmall_content_snapshots      shoppingmall_content_snapshots[]
  shoppingmall_favorites              shoppingmall_favorites[]
  shoppingmall_favorite_addresses     shoppingmall_favorite_addresses[]
  shoppingmall_favorite_notifications shoppingmall_favorite_notifications[]
  shoppingmall_favorite_restore_logs  shoppingmall_favorite_restore_logs[]

  @@unique([customer_id])
  @@unique([seller_id])
  @@unique([admin_id])
  @@index([profile_type])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Manages authentication/verification workflows for actors: 2FA tokens,
/// email/phone verification, password resets, device and session validates.
/// Linked to actor profile, with strong audit controls. Trackable by status,
/// expiry, intent, and used for compliance evidence of verification status
/// at point-in-time.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_auth_verifications {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// References the actor profile for whom this verification was issued.
  actor_id String @db.Uuid

  /// Type of verification or token purpose (email, phone, password_reset, mfa,
  /// onboarding, etc.).
  verification_type String

  /// Secret/token used as proof of verification or reset intent. Generally
  /// time-limited/one-time-use.
  token String

  /// Lifecycle status of the token (pending, used, expired, revoked, etc.).
