/// Immutable audit trail for all role grant/revocation/change actions.
/// Permanent evidence supporting regulatory, legal, and trust/abuse
/// investigations. Captures before/after role states, actor, initiator,
/// timestamps, justifications, and business context. Used extensively by
/// compliance monitoring and admin dashboards.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_role_change_audits {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Actor profile directly affected by the role change event.
  actor_id String @db.Uuid

  /// Role change event type (grant, revoke, expire, escalate, demote, etc.).
  event_type String

  /// Role the actor held prior to event.
  old_role String?

  /// Role assigned by this event (null for demote/revoke lapses).
  new_role String?

  /// The business identifier for the user/admin/process who initiated the role
  /// change.
  changed_by String

  /// Human or system-entered justification for the role mutation; used for
  /// compliance/audit discovery.
  reason String?

  /// Timestamp event occurred as recorded by system clock.
  change_at DateTime @db.Timestamptz

  /// Record creation time for audit traceability.
  created_at DateTime @db.Timestamptz

  /// Last update applied (should only be timestamped for technical
  /// adjustments, never for business content changes).
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  actor shoppingmall_actor_profiles @relation(fields: [actor_id], references: [id], onDelete: Cascade)

  @@unique([actor_id, change_at])
  @@index([actor_id])
  @@index([event_type])
}

schemas.schema-03-sales.prisma:
/// Represents a single product listing in the shopping mall catalog,
/// including base business, pricing, descriptive, and compliance-related
/// data. Major relationships include options (shoppingmall_product_options),
/// media (shoppingmall_product_media), associated tags (via
/// shoppingmall_product_tags), and snapshot versioning
/// (shoppingmall_product_snapshots). Main lifecycle: sellers create, update,
/// and deactivate products; admins may moderate or suspend. Historical state
/// is preserved via @link shoppingmall_product_snapshots.
///
/// @namespace Sales
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_products {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Assigned category's {@link shoppingmall_categories.id}. Each product must
  /// belong to one category.
  shoppingmall_category_id String @db.Uuid

  /// Product owner's seller account {@link shoppingmall_sellers.id}.
  /// References the seller responsible for this product.
  shoppingmall_seller_id String @db.Uuid

  /// Stock-keeping unit code as unique business identifier per product; unique
  /// within the platform.
  sku String

  /// Product name/title for catalog and search display.
  name String

  /// Long-form product description, supports rich text/markdown for customer
  /// detail.
  description String?

  /// Standard price for a single unit in the product's default configuration.
  /// Excludes option upcharges, taxes, discounts.
  base_price Float @db.DoublePrecision

  /// ISO 4217 currency code representing product default currency (e.g.,
  /// 'USD', 'EUR', 'KRW').
  currency String

  /// Product status such as active, inactive, suspended, compliance_hold
  /// (business/application-driven status, not an enum here for extensibility).
  status String

  /// Primary display image URI for fast catalog rendering.
  main_image_uri String? @db.VarChar(80000)

  /// Primary display video URI for product feature/preview (e.g., for
  /// video-rich listings).
  main_video_uri String? @db.VarChar(80000)

  /// Ordering index for product sort within its category or custom listings.
  sort_index Int @db.Integer

  /// Whether this product is flagged for compliance/business review (true =
  /// under review or hold).
  compliance_flag Boolean

  /// Product creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Product last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Product soft-deletion timestamp, if deleted; null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  category shoppingmall_categories @relation(fields: [shoppingmall_category_id], references: [id], onDelete: Cascade)
  seller   shoppingmall_sellers    @relation(fields: [shoppingmall_seller_id], references: [id], onDelete: Cascade)

  shoppingmall_product_options   shoppingmall_product_options[]
  shoppingmall_product_snapshots shoppingmall_product_snapshots[]
  shoppingmall_product_tags      shoppingmall_product_tags[]
  shoppingmall_product_media     shoppingmall_product_media[]
  shoppingmall_inventory_logs    shoppingmall_inventory_logs[]
  shoppingmall_seo_metadata      shoppingmall_seo_metadata[]
  shoppingmall_cart_items        shoppingmall_cart_items[]
  shoppingmall_inquiries         shoppingmall_inquiries[]
  shoppingmall_reviews           shoppingmall_reviews[]
  shoppingmall_favorite_products shoppingmall_favorite_products[]

  @@unique([sku])
  @@index([shoppingmall_category_id, status])
  @@index([shoppingmall_seller_id, created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Defines structured product groupings for catalog navigation and AI
/// search. Supports hierarchical relationships for nested categories. Used
/// in {@link shoppingmall_products}, and may reference templates ({@link
/// shoppingmall_category_templates}).
///
/// @namespace Sales
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent category self-reference {:link shoppingmall_categories.id}.
  /// Enables hierarchical categories.
  parent_id String? @db.Uuid

  /// Applied template's {@link shoppingmall_category_templates.id} for config,
  /// validation, and layout.
  shoppingmall_category_template_id String? @db.Uuid

  /// Machine-unique category code (used for lookups, templates, and
  /// multi-language mapping).
  code String

  /// Human-readable category name for display and navigation.
  name String

  /// Hierarchy level: 0=Root, 1=Level1, etc. For limiting depth/use.
  depth Int @db.Integer

  /// Order within parent for catalog displays.
  sort_index Int @db.Integer

  /// Whether this category is currently enabled/visible.
  active Boolean

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft-delete timestamp (logical removal).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  parent   shoppingmall_categories?         @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)
  template shoppingmall_category_templates? @relation(fields: [shoppingmall_category_template_id], references: [id], onDelete: Cascade)

  shoppingmall_products     shoppingmall_products[]
  recursive                 shoppingmall_categories[]   @relation("recursive")
  shoppingmall_seo_metadata shoppingmall_seo_metadata[]

  @@unique([code])
  @@unique([name, parent_id])
  @@index([shoppingmall_category_template_id])
  @@index([parent_id, active])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Configurable options (e.g., color, size, bundle) associated with a
/// product. Each option defines a type, display name, and business logic for
/// variants. Related option values are in
/// shoppingmall_product_option_values.
///
/// @namespace Sales
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_product_options {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Associated product's {@link shoppingmall_products.id}.
  shoppingmall_product_id String @db.Uuid

  /// Business type (e.g., dropdown, radio, colorpicker, custom). String for
  /// extensibility.
  option_type String

  /// Option display name (shown to users, e.g., Color, Size).
  name String

