  shoppingmall_favorite_products shoppingmall_favorite_products[]

  @@index([shoppingmall_product_id, snapshot_created_at], map: "shoppingmall_product_snapshots_shoppingmall_product_id_407bf308")
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Reusable templates for category logic (validation, presentation, or
