schemas.schema-06-coupons.prisma:
/// Defines the master templates for coupons, including rules for benefit
/// calculation, eligibility, allowed stacking, redemption windows, and
/// associated metadata. This table structures business logic applicable to
/// batches of issued coupons and supports both platform (admin) and
/// seller-originated campaigns. Supports audit trails for retroactive policy
/// changes and analytics for benefit optimization.
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_coupon_templates {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Admin's {@link shoppingmall_admins.id} who created this coupon template.
  created_by_admin_id String? @db.Uuid

  /// Seller's {@link shoppingmall_sellers.id} who created this coupon template
  /// (nullable if admin-created).
  created_by_seller_id String? @db.Uuid

  /// Type of coupon: one of fixed_amount, percentage, free_shipping, etc. Used
  /// for determining benefit calculation logic.
  type String

  /// Business-facing name of the coupon template.
  name String

  /// Long-form business description for the template, explaining business
  /// context, user eligibility, and restriction rules.
  description String?

  /// Window start timestamp when coupons based on this template become valid
  /// for redemption.
  start_at DateTime @db.Timestamptz

  /// Window end timestamp after which no more coupons from this template can
  /// be issued or redeemed.
  end_at DateTime @db.Timestamptz

  /// Business rule: minimum order amount required to enable coupon usage (if
  /// applicable).
  min_order_amount Float? @db.DoublePrecision

  /// Maximum discount amount allowed for this template, used to cap value in
  /// percent-based or stackable offers.
  max_discount_amount Float? @db.DoublePrecision

  /// Total number of coupons issued from this template.
  issued_quantity Int @db.Integer

  /// Maximum number of times a single user can redeem coupons from this
  /// template.
  allowed_uses_per_user Int @db.Integer

  /// Indicates whether coupons using this template can be stacked (combined)
  /// with others in a single order.
  combinable Boolean

  /// Shows if the template is currently active (no subsequent issuance if
  /// false).
  active Boolean

  /// Business extensibility field for extra metadata (JSON encoded for
  /// flexible business logic).
  metadata_json String?

  /// Template creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last template modification timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft-deletion timestamp, null until business removal required.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  createdByAdmin  shoppingmall_admins?  @relation(fields: [created_by_admin_id], references: [id], onDelete: Cascade)
  createdBySeller shoppingmall_sellers? @relation(fields: [created_by_seller_id], references: [id], onDelete: Cascade)

  shoppingmall_coupons shoppingmall_coupons[]

  @@unique([name])
  @@index([created_by_admin_id])
  @@index([created_by_seller_id])
  @@index([type])
  @@index([start_at, end_at])
}

/// Represents individual coupons issued to the platform or sellers,
