  @@index([published_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Threaded comments for UGC articles, inquiries, reviews, or bulletins.
/// Supports nested replies via parent-child hierarchy. Moderation,
/// reporting, evidence, and analytics handled by related models. Each
/// comment links to content target, owning actor, and may be soft-deleted.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_comments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Self-referential. The parent comment's {@link shoppingmall_comments.id},
  /// for nested comment threads.
  parent_id String? @db.Uuid

  /// The root thread's {@link shoppingmall_thread_statistics.id} this comment
  /// belongs to, grouping all comments for a single content object.
  thread_id String @db.Uuid

  /// Actor's {@link shoppingmall_actor_profiles.id} who posted the comment.
  author_id String @db.Uuid

  /// Comment message content. Plain text or optionally formatted by policy.
  body String

  /// Whether this comment has been edited after initial submission. Used for
  /// audit and display.
  edited Boolean

  /// Datetime when comment was first created. Immutable.
  created_at DateTime @db.Timestamptz

  /// Datetime when comment was last edited. Changes if edited=true.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion field. Null unless deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  parent shoppingmall_comments?         @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)
  thread shoppingmall_thread_statistics @relation(fields: [thread_id], references: [id], onDelete: Cascade)
  author shoppingmall_actor_profiles    @relation(fields: [author_id], references: [id], onDelete: Cascade)

  recursive                     shoppingmall_comments[]         @relation("recursive")
  shoppingmall_reported_content shoppingmall_reported_content[]
  shoppingmall_content_flags    shoppingmall_content_flags[]

  @@index([thread_id])
  @@index([author_id])
  @@index([parent_id])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Product, service, or bulletin Q&A inquiries initiated by authenticated
/// users. Each inquiry is linked to a product, article, or bulletin (via
/// foreign key or thread linkage), supports status tracking, moderation, and
/// evidence/audit via snapshots. Answers are managed in separate table.
/// Reporting, flagging, and compliance handled via related entities.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_inquiries {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The root thread's {@link shoppingmall_thread_statistics.id} for this
  /// inquiry (groups all posts: Q&A, comments, stats, etc.).
  thread_id String @db.Uuid

  /// Inquiry by customer's {@link shoppingmall_customers.id}.
  customer_id String @db.Uuid

  /// Target product's {@link shoppingmall_products.id} (if product inquiry).
  target_product_id String? @db.Uuid

  /// Target article's {@link shoppingmall_articles.id} (if article inquiry).
  target_article_id String? @db.Uuid

  /// Target bulletin's {@link shoppingmall_bulletins.id} (if bulletin inquiry).
  target_bulletin_id String? @db.Uuid

  /// Full inquiry question submitted by user. Subject to profanity check,
  /// validation. Min 10, max 1000 characters.
  question String

  /// Business status code of inquiry: pending, answered, closed, or escalated,
  /// per business rules.
  status String

  /// Datetime of inquiry submission. Immutable, for evidence and search.
  created_at DateTime @db.Timestamptz

  /// Datetime of most recent inquiry update or status change.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion. Set when logically removed for compliance, evidence, or
  /// policy.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  thread   shoppingmall_thread_statistics @relation(fields: [thread_id], references: [id], onDelete: Cascade)
  customer shoppingmall_customers         @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  product  shoppingmall_products?         @relation(fields: [target_product_id], references: [id], onDelete: Cascade)
  article  shoppingmall_articles?         @relation(fields: [target_article_id], references: [id], onDelete: Cascade)
  bulletin shoppingmall_bulletins?        @relation(fields: [target_bulletin_id], references: [id], onDelete: Cascade)

  shoppingmall_inquiry_answers    shoppingmall_inquiry_answers?
  shoppingmall_reported_content   shoppingmall_reported_content[]
  shoppingmall_content_flags      shoppingmall_content_flags[]
  shoppingmall_favorite_inquiries shoppingmall_favorite_inquiries[]

  @@unique([question, customer_id, created_at])
  @@index([target_product_id])
  @@index([target_article_id])
  @@index([target_bulletin_id])
  @@index([thread_id])
  @@index([customer_id])
  @@index([status])
  @@index([question(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Official answers (from seller or admin) to inquiries. Answers are 1:1
/// with inquiries but may support edits and history (tracked by snapshots).
/// Clearly associated to responding actor, with audit and compliance
/// requirements. Used for business/role escalation workflows.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_inquiry_answers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Target inquiry's {@link shoppingmall_inquiries.id} being answered.
  inquiry_id String @db.Uuid

  /// Actor's {@link shoppingmall_actor_profiles.id} who responded. Must be
  /// seller or admin.
  responder_id String @db.Uuid

  /// Answer message content. May support rich text or formatting depending on
  /// business logic.
  body String

  /// Whether this answer has been edited after initial submission. Used for
  /// audit purposes.
  edited Boolean

  /// Datetime when answer was first created. Immutable.
  created_at DateTime @db.Timestamptz

  /// Datetime when answer was last edited. Changes if edited=true.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion field. Set when answer removed logically, retained for
  /// audit.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  inquiry   shoppingmall_inquiries      @relation(fields: [inquiry_id], references: [id], onDelete: Cascade)
  responder shoppingmall_actor_profiles @relation(fields: [responder_id], references: [id], onDelete: Cascade)

  shoppingmall_favorite_inquiries shoppingmall_favorite_inquiries[]

  @@unique([inquiry_id])
  @@index([inquiry_id])
  @@index([responder_id])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Product, service, or seller reviews entered by customers after
/// purchase/fulfillment. Each review links to a thread, the reviewed entity
/// (product or seller), and the submitting customer. Supported features:
/// star rating, text content, optional media, moderation, reporting, and
/// analytics. Review edits and compliance evidence retained via snapshots.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_reviews {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The root thread's {@link shoppingmall_thread_statistics.id} for this
  /// review and all replies/posts.
  thread_id String @db.Uuid

  /// Authoring customer's {@link shoppingmall_customers.id}.
  customer_id String @db.Uuid

  /// Reviewed product's {@link shoppingmall_products.id}. Null if not a
  /// product review.
  target_product_id String? @db.Uuid

  /// Reviewed seller's {@link shoppingmall_sellers.id}. Null if not seller
  /// review.
  target_seller_id String? @db.Uuid

  /// Business review score. 1 to 5 stars, inclusive. Enforced by validation
  /// logic.
  rating Int @db.Integer

  /// Short review title, used in lists or search. Optional.
  title String?

  /// Review content body. Min 10, max 2000 characters. Must pass validation
  /// and moderation.
  body String

  /// Indicates if review is from a verified purchase/order (for business trust
  /// badge display).
  verified_purchase Boolean

  /// Datetime of review submission. Immutable, for time-based sort or evidence.
  created_at DateTime @db.Timestamptz

  /// Datetime of most recent review update (body, title, etc).
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp, if removed logically for policy/compliance.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  thread   shoppingmall_thread_statistics @relation(fields: [thread_id], references: [id], onDelete: Cascade)
  customer shoppingmall_customers         @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  product  shoppingmall_products?         @relation(fields: [target_product_id], references: [id], onDelete: Cascade)
  seller   shoppingmall_sellers?          @relation(fields: [target_seller_id], references: [id], onDelete: Cascade)

  shoppingmall_review_replies   shoppingmall_review_replies?
  shoppingmall_reported_content shoppingmall_reported_content[]
  shoppingmall_content_flags    shoppingmall_content_flags[]

  @@unique([thread_id, customer_id, target_product_id], map: "shoppingmall_reviews_thread_id_customer_id_target_prod_518603d3")
  @@unique([thread_id, customer_id, target_seller_id])
  @@index([thread_id])
  @@index([customer_id])
  @@index([target_product_id])
  @@index([target_seller_id])
  @@index([rating])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Authoritative replies to reviews from sellers or admins. One reply per
/// review. Replies support moderation, edits, evidence/audit, and can be
/// flagged for abuse. Each is associated to a review and responding actor
/// role.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_review_replies {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Target review's {@link shoppingmall_reviews.id} being replied to.
  review_id String @db.Uuid

  /// Actor's {@link shoppingmall_actor_profiles.id} replying to the review.
  /// Usually a seller or admin.
  responder_id String @db.Uuid

  /// Reply message content, including moderation notes or acknowledgments.
  body String

  /// Whether this reply has been edited after submission. Required for
  /// evidence and audit.
  edited Boolean

  /// Creation datetime of review reply. Immutable.
  created_at DateTime @db.Timestamptz

  /// Datetime of most recent edit to reply.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion flag. Set when reply logically deleted (policy/compliance).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  review    shoppingmall_reviews        @relation(fields: [review_id], references: [id], onDelete: Cascade)
  responder shoppingmall_actor_profiles @relation(fields: [responder_id], references: [id], onDelete: Cascade)

  @@unique([review_id])
  @@index([review_id])
  @@index([responder_id])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Bulletin board posts and platform-wide announcements. Created mainly by
/// admins but can be posted by designated sellers for community marketing,
/// legal, or major campaign notices. Supports pinning, expiration, and
/// visibility logic. Audit and content evidence preserved for compliance
/// uses. Comments and reporting supported via related models.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_bulletins {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Actor's {@link shoppingmall_actor_profiles.id} who posted the bulletin
  /// (admin or seller).
  author_id String @db.Uuid

  /// Bulletin headline or title. Used for listings, links, and notifications.
  title String

  /// Bulletin message content. Can include formatting, images, or legal text.
  body String

  /// If the bulletin is currently pinned at the top of listings. Admin only.
  pinned Boolean

  /// Visibility policy: all, customers, sellers, or admin-only. Used to
  /// restrict who sees a post.
  visible_to String

  /// Optional expiration; bulletin hidden after this date for users.
  expire_at DateTime? @db.Timestamptz

  /// Datetime of creation. Immutable, for evidence and compliance.
  created_at DateTime @db.Timestamptz

  /// Datetime of last edit or update. Tracked for moderation/audit.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion. Set when logically removed, but still retained for
  /// compliance period.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  author shoppingmall_actor_profiles @relation(fields: [author_id], references: [id], onDelete: Cascade)

  shoppingmall_inquiries        shoppingmall_inquiries[]
  shoppingmall_reported_content shoppingmall_reported_content[]
  shoppingmall_content_flags    shoppingmall_content_flags[]

  @@unique([title, created_at])
  @@index([author_id])
  @@index([pinned])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Business-level content abuse or violation reports filed by users or
/// detected by automated systems. Supports multi-type (comment, review,
/// bulletin, article, etc.) targeting, links to reporting actor, management
/// status, and audit evidence. Used for moderation, compliance, and
/// regulatory escalation when required.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_reported_content {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Actor's {@link shoppingmall_actor_profiles.id} who filed the report
  /// (customer, seller, or admin).
  reported_by_id String @db.Uuid

  /// Reported comment's {@link shoppingmall_comments.id}, if report is for a
  /// comment.
  target_comment_id String? @db.Uuid

  /// Reported article's {@link shoppingmall_articles.id}, if report is for
  /// article.
  target_article_id String? @db.Uuid

  /// Reported inquiry's {@link shoppingmall_inquiries.id}, if applicable.
  target_inquiry_id String? @db.Uuid

  /// Reported review's {@link shoppingmall_reviews.id}, if applicable.
  target_review_id String? @db.Uuid

  /// Reported bulletins's {@link shoppingmall_bulletins.id}, if applicable.
  target_bulletin_id String? @db.Uuid

  /// Machine- or user-generated reason code: spam, abuse, fraud, policy,
  /// legal, etc. Used for escalation path and analytics.
  reason_code String

  /// Additional free-text context or details from the reporter. May be null
  /// for automated detection.
  narrative String?

  /// Status of the report: open, reviewed, actioned, closed, escalated, etc.
  /// Tracked for compliance evidence.
  status String

  /// Date/time report was filed or auto-generated. Immutable, for business
  /// logic and SLA audit.
  created_at DateTime @db.Timestamptz

  /// Date/time of last moderation action or status update. Changes as review
  /// proceeds.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion for compliance evidence, set when logically removed.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  reporter shoppingmall_actor_profiles @relation(fields: [reported_by_id], references: [id], onDelete: Cascade)
  comment  shoppingmall_comments?      @relation(fields: [target_comment_id], references: [id], onDelete: Cascade)
  article  shoppingmall_articles?      @relation(fields: [target_article_id], references: [id], onDelete: Cascade)
  inquiry  shoppingmall_inquiries?     @relation(fields: [target_inquiry_id], references: [id], onDelete: Cascade)
  review   shoppingmall_reviews?       @relation(fields: [target_review_id], references: [id], onDelete: Cascade)
  bulletin shoppingmall_bulletins?     @relation(fields: [target_bulletin_id], references: [id], onDelete: Cascade)

  @@index([target_comment_id])
  @@index([target_article_id])
  @@index([target_inquiry_id])
  @@index([target_review_id])
  @@index([target_bulletin_id])
  @@index([reported_by_id])
  @@index([status])
  @@index([narrative(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Internal or user-triggered moderation flags on content. Used to mark
/// possible abuse, offensive, or out-of-policy cases pending review.
/// Actioned by admins, linked to flagged actor, content, and
/// compliance/audit evidence. Subject to auto-escalation on threshold or
/// legal/AI detection.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_content_flags {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Actor's {@link shoppingmall_actor_profiles.id} who flagged the content
  /// (or system/AI).
  flagged_by_id String @db.Uuid

  /// Flagged comment's {@link shoppingmall_comments.id}, if content is comment.
  target_comment_id String? @db.Uuid

  /// Flagged article's {@link shoppingmall_articles.id}, if content is article.
  target_article_id String? @db.Uuid

  /// Flagged inquiry's {@link shoppingmall_inquiries.id}, if content is
  /// inquiry.
  target_inquiry_id String? @db.Uuid

  /// Flagged review's {@link shoppingmall_reviews.id}, if content is review.
  target_review_id String? @db.Uuid

  /// Flagged bulletins's {@link shoppingmall_bulletins.id}, if content is
  /// bulletin.
  target_bulletin_id String? @db.Uuid

  /// Flag category code: abuse, spam, copyright, prohibited, etc. Used for
  /// business rule/action routing.
  flag_type String

  /// Free-text note from actor, may include context or evidence pointer. May
  /// be null for automated/AI flags.
  note String?

  /// Status of moderation: pending, reviewed, actioned, dismissed.
  status String

  /// When flagged record was created (user or automated). Immutable for
  /// evidence and audit.
  created_at DateTime @db.Timestamptz

  /// Datetime last updated, typically by moderator or system.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion field for legal compliance/audit retention.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  flaggedBy shoppingmall_actor_profiles @relation(fields: [flagged_by_id], references: [id], onDelete: Cascade)
  comment   shoppingmall_comments?      @relation(fields: [target_comment_id], references: [id], onDelete: Cascade)
  article   shoppingmall_articles?      @relation(fields: [target_article_id], references: [id], onDelete: Cascade)
  inquiry   shoppingmall_inquiries?     @relation(fields: [target_inquiry_id], references: [id], onDelete: Cascade)
  review    shoppingmall_reviews?       @relation(fields: [target_review_id], references: [id], onDelete: Cascade)
  bulletin  shoppingmall_bulletins?     @relation(fields: [target_bulletin_id], references: [id], onDelete: Cascade)

  @@index([target_comment_id])
  @@index([target_article_id])
  @@index([target_inquiry_id])
  @@index([target_review_id])
  @@index([target_bulletin_id])
  @@index([flagged_by_id])
  @@index([status])
  @@index([note(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Immutable snapshots of content items (comments, reviews, inquiries,
/// articles, bulletins, etc.) for compliance, audit, dispute resolution, or
/// history navigation. Each links to original content, content type, and
/// change context. Tied to thread and actor. Only created by business events
/// (change, deletion, dispute, etc.).
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_content_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Content thread's {@link shoppingmall_thread_statistics.id} for full audit
  /// trail linkage.
  thread_id String @db.Uuid

  /// Actor's {@link shoppingmall_actor_profiles.id} who triggered the snapshot
  /// (admin, seller, customer, or system).
  actor_id String @db.Uuid

  /// Content type: comment, review, inquiry, article, bulletin, etc. Used to
  /// interpret content_id and reconstruction.
  content_type String

  /// UUID of the content object being snapshotted. Must correspond to correct
  /// type/target table.
  content_id String @db.Uuid

  /// Full serialized snapshot of content at the time of event. Content
  /// structure depends on type.
  snapshot_body String

  /// Business code for what caused snapshot (create, edit, delete, moderation,
  /// dispute, etc.).
  change_event String

  /// Snapshot creation datetime. Immutable evidence timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  thread shoppingmall_thread_statistics @relation(fields: [thread_id], references: [id], onDelete: Cascade)
  actor  shoppingmall_actor_profiles    @relation(fields: [actor_id], references: [id], onDelete: Cascade)

  @@unique([content_id, change_event, created_at], map: "shoppingmall_content_snapshots_content_id_change_event_a62eed66")
  @@index([thread_id])
  @@index([actor_id])
  @@index([content_type])
  @@index([snapshot_body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Materialized/statistics entity for each thread of user/community content
/// (article, review thread, inquiry thread, bulletin thread, etc.). Stores
/// denormalized statistics and trust signals (post count, like count, abuse
/// count, moderation history) for performance analytics and UI display.
/// Serves as anchor/root for comments and thread association. Managed as
/// non-materialized business table for performance and audit requirements,
/// not for direct content display.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_thread_statistics {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Thread context type: article, review, inquiry, bulletin, etc. Used for
  /// analytics and UGC linkage.
  thread_type String

  /// UUID of top-level content entity this thread is for (article, review,
  /// inquiry, etc).
  target_id String @db.Uuid

  /// Denormalized count of posts/comments/content in this thread. Used for
  /// analytics and query performance.
  post_count Int @db.Integer

  /// Like/upvote count associated with content in this thread. Used for
  /// trust/trending UI.
  like_count Int @db.Integer

  /// Count of abuse/report/flag submissions related to thread content. Tracked
  /// for moderation escalation and analytics.
  abuse_report_count Int @db.Integer

  /// Datetime when last post was made to this thread (audit, recency ranking).
  last_posted_at DateTime? @db.Timestamptz

  /// Thread statistics row creation datetime.
  created_at DateTime @db.Timestamptz

  /// Datetime statistics row was last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  shoppingmall_comments          shoppingmall_comments[]
  shoppingmall_inquiries         shoppingmall_inquiries[]
  shoppingmall_reviews           shoppingmall_reviews[]
  shoppingmall_content_snapshots shoppingmall_content_snapshots[]

  @@unique([thread_type, target_id])
  @@index([last_posted_at])
}

schemas.schema-08-favorites.prisma:
/// Stores summary record of all favorites for a user, with role,
/// entity-type, current status, and logical deletion. References user
/// (customer, seller), relates to specific domains such as products,
/// inquiries, or addresses. Central linking table for favorites logic. Used
/// for managing favorites lifecycle, restoration, deactivation, and
/// engagement analytics.
///
/// @namespace Favorites
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_favorites {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Actor performing the favoriting action. References the user's {@link
  /// shoppingmall_actor_profiles.id}.
  actor_profile_id String @db.Uuid

  /// Type of entity being favorited (e.g., 'product', 'inquiry', 'address').
  /// Defines the linked domain for the favorite record.
  target_type String

  /// ID of the entity being favorited, variable by type (product, inquiry,
  /// address).
  target_id String @db.Uuid

  /// Timestamp when favorite was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when favorite was last updated (modify, restore, remove).
  updated_at DateTime @db.Timestamptz

  /// Soft delete indicator for favorite removal/reversal. Null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  actorProfile shoppingmall_actor_profiles @relation(fields: [actor_profile_id], references: [id], onDelete: Cascade)

  shoppingmall_favorite_products      shoppingmall_favorite_products?
  shoppingmall_favorite_inquiries     shoppingmall_favorite_inquiries?
  shoppingmall_favorite_addresses     shoppingmall_favorite_addresses?
  shoppingmall_favorite_snapshots     shoppingmall_favorite_snapshots[]
  shoppingmall_favorite_events        shoppingmall_favorite_events[]
