/// Record of compliance-related events, such as audits, regulatory
/// inquiries, or major business rule changes. Used for policy review,
/// compliance audit, and incident response. Can reference external objects
/// (by UUID) and evidence bundles.
///
/// @namespace BusinessRules
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_compliance_events {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Linked evidence bundle for this event's documentation {@link
  /// shoppingmall_evidence_bundles.id}.
  evidence_bundle_id String? @db.Uuid

  /// Business event type (e.g., audit, report, inquiry, breach, remediation).
  event_type String

  /// Event status code (open, resolved, under_review, etc.).
  event_status String

  /// Brief summary/narrative of the compliance event.
  summary String

  /// Extended textual description or findings from event/audit.
  description String

  /// Type of entity affected by or origin of event.
  related_object_type String?

  /// UUID of related entity.
  related_object_id String? @db.Uuid

  /// Timestamp at which event occurred.
  occurred_at DateTime @db.Timestamptz

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Record update timestamp.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
