  @@index([evidence_bundle_id])
  @@index([event_type])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Audit log of business rule changes, assignments, applications, and status
/// transitions. Central for system-wide auditability, regulatory compliance
/// evidence, and admin controls. Logs all actions on rules including who,
/// what, when, reason, and chain of historical changes.
///
/// @namespace BusinessRules
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shoppingmall_rules_audit {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Associated rule's {@link shoppingmall_business_rules.id}.
