  /// Type of incident (data_breach, policy_violation, regulatory_inquiry,
  /// etc.).
  incident_type String

  /// Incident status code (open, mitigated, resolved, escalated,
  /// under_investigation, etc.).
  incident_status String

  /// Narrative summary of incident business impact/outcome.
  impact_summary String

  /// Structured or free-text report of incident event sequence (may be
  /// JSON/text).
  timeline String

  /// User/admin/service who submitted the report.
  reported_by_actor_id String @db.Uuid

  /// Timestamp of initial report submission.
  reported_at DateTime @db.Timestamptz

  /// Timestamp of incident resolution (null if unresolved).
  resolved_at DateTime? @db.Timestamptz

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Record update timestamp.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  evidenceBundle shoppingmall_evidence_bundles? @relation(fields: [evidence_bundle_id], references: [id], onDelete: Cascade)

  @@index([evidence_bundle_id])
  @@index([incident_type])
  @@index([impact_summary(ops: raw("gin_trgm_ops"))], type: Gin)
}

